fn fresh_state_with_enemy(hp: i32) -> (CombatState, CreatureUid) {
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    // Bead `sts2-rs-hdy`: seed a non-zero player HP so handlers that
    // route self-damage through `apply_damage_to_player` (Bloodletting,
    // Hemokinesis, DemonicShield, Offering) don't trip the
    // dead-player early-return in `self_hp_loss`. 80/80 is the same
    // baseline used by silent.rs test fixtures.
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let id = NonZeroU32::new(1).expect("non-zero");
    state.creatures.push(Creature {
        id,
        current_hp: hp,
        max_hp: hp,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let uid = CreatureUid(id);
    state.enemy_uids.push(uid);
    (state, uid)
}

/// Push a card POD into `state.cards` and add it to the Play pile.
/// Returns the `CardUid` (1-based).
fn push_play_card(
    state: &mut CombatState,
    card_id: CardId,
    base_damage: i32,
    base_block: i32,
) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage,
        base_block,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.play.push(uid);
    uid
}

/// Push a card POD into `state.cards` and add it to the TOP of the
/// draw pile. Returns the `CardUid` (1-based).
fn push_draw_card(
    state: &mut CombatState,
    card_id: CardId,
    card_type: CardType,
    target_type: TargetType,
) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type,
        target_type,
        upgraded: false,
        base_damage: 0,
        base_block: 5,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.draw.insert(0, uid);
    uid
}

/// q6bix F-F: `auto_play_card_from_draw_top(state, false)` must route a
/// NON-exhaust card to the DISCARD pile (C# `AutoPlayFromDrawPile`
/// sets `ExhaustOnNextPlay = forceExhaust`, so `false` = natural
/// routing). Cascade / DistilledChaos / Imbued use `false`; only Havoc
/// uses `true`. The helper previously hard-coded force-exhaust, wrongly
/// exhausting Cascade's replayed cards.
#[test]
fn q6bix_auto_play_force_exhaust_false_routes_to_discard() {
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(50);
    let uid = push_draw_card(
        &mut state,
        CardId::DefendIronclad,
        CardType::Skill,
        TargetType::Self_,
    );
    let played = sts2_core::combat_loop::auto_play_card_from_draw_top(
        &mut state, /*force_exhaust=*/ false,
    );
    assert!(played, "a card was auto-played");
    assert!(
        state.player.discard.contains(&uid),
        "non-exhaust card routes to DISCARD when force_exhaust=false"
    );
    assert!(
        !state.player.exhaust.contains(&uid),
        "must NOT be exhausted"
    );
}

/// q6bix F-F: `force_exhaust=true` (Havoc) still exhausts the card.
