/// Bead `sts2-rs-jjref`: PerfectedStrike's damage multiplier counts
/// Strike-TAGGED cards across the FIVE live piles only (C#
/// `AllCards = AllPiles.SelectMany(Cards)`), NOT the raw `state.cards`
/// instance arena — an ORPHANED Strike instance (in `state.cards` but no
/// pile, e.g. a leaked SeekerStrike copy) must NOT inflate the count.
#[test]
fn perfected_strike_counts_pile_strikes_not_orphans() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(400);
    // Helper: push a Strike-tagged card POD into `state.cards`, returning
    // its uid (the caller decides which pile, if any, to add it to).
    let push_strike = |state: &mut CombatState, id: CardId| -> sts2_core::CardUid {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: id,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: sts2_core::cards::CombatVars::new(),
            enchantments: sts2_core::cards::CardEnchantments::new(),
            tags: CardTags::one(sts2_core::cards::CardTag::Strike),
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        uid
    };
    // PerfectedStrike itself in Play (the card being resolved), plus a
    // Strike in Hand and one in Discard → 3 live-pile strikes.
    let ps = push_strike(&mut state, CardId::PerfectedStrike);
    state.player.play.push(ps);
    let h = push_strike(&mut state, CardId::StrikeIronclad);
    state.player.hand.push(h);
    let d = push_strike(&mut state, CardId::StrikeIronclad);
    state.player.discard.push(d);
    // An ORPHAN Strike instance: in `state.cards` but in NO pile.
    let _orphan = push_strike(&mut state, CardId::SeekerStrike);

    let hp0 = state.creatures[0].current_hp;
    let _ = dispatch(&mut state, CardId::PerfectedStrike, Some(enemy));
    // base 6 + 2/strike × 3 live-pile strikes = 12 (orphan excluded).
    assert_eq!(
        hp0 - state.creatures[0].current_hp,
        12,
        "PerfectedStrike counts 3 live-pile strikes, not the orphan (would be 14)"
    );
}

#[test]
fn ironclad_power_amounts_scale_with_upgrade() {
    // C# OnUpgrade bumps these power/debuff amounts. Bead ja5qw.
    install_pool();
    let player_power = |card: CardId, kind: PowerKind, upgraded: bool| -> Option<i32> {
        let (mut state, enemy) = fresh_state_with_enemy(200);
        let _ = push_play_card(&mut state, card, 0, 0);
        state.cards.last_mut().expect("pushed").upgraded = upgraded;
        let _ = lookup(card).expect("registered")(&mut state, Some(enemy));
        state.player.powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == kind)
                .map(|p| p.amount)
        })
    };
    for (card, kind, base, up) in [
        (CardId::SetupStrikeCard, PowerKind::SetupStrike, 2, 3),
        (CardId::InfernoCard, PowerKind::Inferno, 6, 9),
        (CardId::StoneArmor, PowerKind::Plating, 4, 6),
        (CardId::DemonFormCard, PowerKind::DemonForm, 2, 3),
        // v0.107.1: Juggernaut base 6 / upgrade 8 (was 5/7).
        (CardId::JuggernautCard, PowerKind::Juggernaut, 6, 8),
        (CardId::CrimsonMantle, PowerKind::CrimsonMantle, 8, 10),
        (CardId::CrueltyCard, PowerKind::Cruelty, 25, 50),
        (CardId::Brand, PowerKind::Strength, 1, 2),
    ] {
        assert_eq!(player_power(card, kind, false), Some(base), "{kind:?} base");
        assert_eq!(
            player_power(card, kind, true),
            Some(up),
            "{kind:?} upgraded"
        );
    }
    // Enemy-targeted debuff amounts: Mangle 10/15, Tremble Vulnerable 3/4.
    let enemy_power = |card: CardId, kind: PowerKind, upgraded: bool| -> Option<i32> {
        let (mut state, enemy) = fresh_state_with_enemy(200);
        let _ = push_play_card(&mut state, card, 15, 0);
        state.cards.last_mut().expect("pushed").upgraded = upgraded;
        let _ = lookup(card).expect("registered")(&mut state, Some(enemy));
        state.creatures[0].powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == kind)
                .map(|p| p.amount)
        })
    };
    assert_eq!(
        enemy_power(CardId::Mangle, PowerKind::ManglePower, false),
        Some(10)
    );
    assert_eq!(
        enemy_power(CardId::Mangle, PowerKind::ManglePower, true),
        Some(15)
    );
    assert_eq!(
        enemy_power(CardId::Tremble, PowerKind::Vulnerable, false),
        Some(3)
    );
    assert_eq!(
        enemy_power(CardId::Tremble, PowerKind::Vulnerable, true),
        Some(4)
    );
}

/// Bead `sts2-rs-setup-str`: Setup Strike grants the matching *real*
/// Strength when played (C# `SetupStrikePower : TemporaryStrengthPower`
/// → `BeforeApplied` applies `StrengthPower(+amount)` silently), so the
/// rest of the turn's attacks hit harder. Regression for the prior
/// marker-only port that left the damage boost inert.
#[test]
fn setup_strike_applies_real_strength_alongside_marker() {
    install_pool();
    let strength_after = |upgraded: bool| -> Option<i32> {
        let (mut state, enemy) = fresh_state_with_enemy(200);
        let _ = push_play_card(&mut state, CardId::SetupStrikeCard, 7, 0);
        state.cards.last_mut().expect("pushed").upgraded = upgraded;
        let _ = lookup(CardId::SetupStrikeCard).expect("registered")(&mut state, Some(enemy));
        state.player.powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == PowerKind::Strength)
                .map(|p| p.amount)
        })
    };
    assert_eq!(
        strength_after(false),
        Some(2),
        "Setup Strike grants +2 Strength"
    );
    assert_eq!(
        strength_after(true),
        Some(3),
        "upgraded Setup Strike grants +3 Strength"
    );
}

/// HEMOKINESIS spec/upgrade pin (C# `Hemokinesis.cs`): 1-cost Uncommon
