/// HEMOKINESIS deals its base/upgraded damage to the target and loses
/// exactly 2 HP, with no Rupture in play. C# `Hemokinesis.cs:28-31`:
/// `CreatureCmd.Damage(self, HpLoss.BaseValue=2, …)` then
/// `DamageCmd.Attack(Damage.BaseValue)`. Bead `sts2-rs-22ttw`.
#[test]
fn hemokinesis_deals_damage_and_loses_two_hp() {
    install_pool();
    let dmg_dealt = |base_damage: i32| -> (i32, i32) {
        let (mut state, enemy) = fresh_state_with_enemy(200);
        state.init_player_creature();
        let hp_before = state.player.current_hp;
        let enemy_before = state.creatures[0].current_hp;
        let _ = push_play_card(&mut state, CardId::Hemokinesis, base_damage, 0);
        let r = dispatch(&mut state, CardId::Hemokinesis, Some(enemy));
        assert_eq!(r, EffectResult::Resolved);
        (
            enemy_before - state.creatures[0].current_hp,
            hp_before - state.player.current_hp,
        )
    };
    assert_eq!(dmg_dealt(15), (15, 2), "base: 15 dmg + 2 self HP loss");
    assert_eq!(dmg_dealt(20), (20, 2), "upgraded: 20 dmg + 2 self HP loss");
}

/// Regression for bead `sts2-rs-22ttw`: with RupturePower in play, the
/// Strength it grants from HEMOKINESIS's OWN self-HP-loss must NOT buff
/// HEMOKINESIS's own attack. C# `RupturePower.AfterDamageReceived`
/// (`RupturePower.cs:45-58`) defers Strength into `playedCards[cardSource]`
/// when the damage's source is the currently-playing card, and applies it
/// only in `AfterCardPlayed` (line 60-66). The prior Rust port applied it
/// immediately, inflating the attack by the Rupture stack and leaving a
/// phantom Strength power mid-card. This test runs the handler (card on the
/// Play pile), so the deferred Strength is parked on the Rupture instance's
/// `counter` and NOT yet on the player.
#[test]
fn hemokinesis_self_damage_does_not_buff_its_own_attack_with_rupture() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    // Seed Rupture(2) on the player BEFORE building the mirror so it lands on
    // the player-Creature too (init clones player.powers into the mirror).
    let rupture_pid = NonZeroU32::new(9001).expect("non-zero");
    state.powers.push(Power {
        id: rupture_pid,
        kind: PowerKind::Rupture,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(rupture_pid));
    state.init_player_creature();
    state.side = sts2_core::Side::Player;

    let enemy_before = state.creatures[0].current_hp;
    let _ = push_play_card(&mut state, CardId::Hemokinesis, 15, 0);
    let _ = dispatch(&mut state, CardId::Hemokinesis, Some(enemy));

    // Attack hit for exactly 15 — NOT 15 + 2 (Strength must not have applied
    // before the attack landed).
    assert_eq!(
        enemy_before - state.creatures[0].current_hp,
        15,
        "Rupture Strength must NOT buff HEMOKINESIS's own attack",
    );
    // No Strength power has been granted to the player yet (deferred).
    assert_eq!(
        state.player_power_amount(PowerKind::Strength),
        0,
        "Rupture Strength is deferred until after the card resolves",
    );
    // The owed Strength (= 2) is parked under Hemokinesis's own entry.
    let hemo = *state.player.play.last().expect("Hemokinesis on Play");
    assert_eq!(
        state.combat_log.rupture_deferred_strength,
        vec![(hemo, 2)],
        "deferred Strength owed to the playing Hemokinesis"
    );
}

/// End-to-end via `combat_loop::play_card`: after HEMOKINESIS fully
/// resolves with Rupture(2) in play, the deferred Strength lands (player has
/// Strength 2) while the attack itself stayed un-buffed (enemy took 15), and
/// there is no phantom mid-card power. Mirrors C# `RupturePower`'s
/// defer-then-`AfterCardPlayed`-apply. Bead `sts2-rs-22ttw`.
#[test]
fn hemokinesis_rupture_strength_lands_after_card_resolves() {
    use sts2_core::combat_loop::play_card;
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);

    let rupture_pid = NonZeroU32::new(9002).expect("non-zero");
    state.powers.push(Power {
        id: rupture_pid,
        kind: PowerKind::Rupture,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(rupture_pid));
    state.init_player_creature();
    state.side = sts2_core::Side::Player;
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.player.energy = 3;
    state.player.max_energy = 3;

    // Build a real Hemokinesis card in HAND (play_card resolves by hand idx).
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let card_uid = sts2_core::CardUid::new(raw).expect("non-zero");
    state.cards.push(Card {
        uid: card_uid,
        card_id: CardId::Hemokinesis,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 15,
        base_block: 0,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.hand.push(card_uid);

    let enemy_before = state.creatures[0].current_hp;
    let enemy_idx = u8::try_from(
        state
            .enemy_uids
            .iter()
            .position(|&u| u == enemy)
            .expect("enemy present"),
    )
    .expect("idx fits");
    let _ = play_card(&mut state, 0, Some(enemy_idx));

    // Attack stayed un-buffed (15), Strength now landed (2), Rupture counter
    // drained back to 0 — no phantom leftover.
    assert_eq!(
        enemy_before - state.creatures[0].current_hp,
        15,
        "attack un-buffed by deferred Rupture Strength",
    );
    assert_eq!(
        state.player_power_amount(PowerKind::Strength),
        2,
        "deferred Rupture Strength applied after the card resolves",
    );
    assert!(
        state.combat_log.rupture_deferred_strength.is_empty(),
        "Rupture deferred-Strength entry drained"
    );
}

/// Galvanic's self-damage lands in the enemy-power lane of a Power card's
/// `AfterCardPlayed`, after `RupturePower.AfterCardPlayed` has already removed
/// that card from `playedCards`, and C# deals it with `cardSource = null`
/// (GalvanicPower.cs AfterCardPlayed; RupturePower.cs AfterDamageReceived).
/// So Rupture grants the Strength at once. A deferred entry under the played
/// card would never drain.
#[test]
fn rupture_strength_from_galvanic_after_a_power_play_is_not_lost() {
    use sts2_core::combat_loop::play_card;
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    let rupture_pid = NonZeroU32::new(9010).expect("non-zero");
    state.powers.push(Power {
        id: rupture_pid,
        kind: PowerKind::Rupture,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(rupture_pid));
    let galvanic_pid = NonZeroU32::new(9011).expect("non-zero");
    state.powers.push(Power {
        id: galvanic_pid,
        kind: PowerKind::Galvanic,
        amount: 6,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[0].powers.push(PowerUid(galvanic_pid));
    state.init_player_creature();
    state.side = sts2_core::Side::Player;
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.player.energy = 3;
    state.player.max_energy = 3;
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let card_uid = sts2_core::CardUid::new(raw).expect("non-zero");
    state.cards.push(Card {
        uid: card_uid,
        card_id: CardId::Inflame,
        cost: 1,
        card_type: CardType::Power,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.hand.push(card_uid);
    sts2_core::monster_power_effects::galvanic_before_combat_start(&mut state);
    let hp_before = state.player.current_hp;
    let _ = play_card(&mut state, 0, None);
    assert_eq!(
        hp_before - state.player.current_hp,
        6,
        "Galvanic dealt its 6"
    );
    assert!(
        state.combat_log.rupture_deferred_strength.is_empty(),
        "no Rupture entry left parked under the finished play"
    );
    // Inflame's 2 (Inflame.cs:18) plus Rupture's 2 for the Galvanic HP loss.
    assert_eq!(state.player_power_amount(PowerKind::Strength), 4);
}

/// Seed 4536 (v0.111 combat sweep, GLOBE_HEAD_NORMAL): Cascade auto-plays a
/// Rupture card, whose Galvanic self-damage (6) must grant Rupture's Strength
/// at once, so the next auto-played attack hits with it. C# `GalvanicPower`
/// deals that damage with `cardSource = null` (GalvanicPower.cs
/// AfterCardPlayed), and `RupturePower.AfterDamageReceived` applies Strength
/// immediately for a null `cardSource` (RupturePower.cs). It must not park it
/// under the enclosing Cascade, which would hold it until Cascade's own
/// after-played and let the Strike miss it (C# hp 91, Rust 92).
#[test]
fn rupture_strength_from_galvanic_in_a_cascade_auto_play_lands_before_the_next_card() {
    use sts2_core::combat_loop::play_card;
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    let galvanic_pid = NonZeroU32::new(9011).expect("non-zero");
    state.powers.push(Power {
        id: galvanic_pid,
        kind: PowerKind::Galvanic,
        amount: 6,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[0].powers.push(PowerUid(galvanic_pid));
    state.init_player_creature();
    state.side = sts2_core::Side::Player;
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.player.energy = 2;
    state.player.max_energy = 3;
    // Draw top = [Rupture, Strike] (each push inserts at the front).
    let _strike = push_draw_top_card(
        &mut state,
        CardId::StrikeIronclad,
        CardType::Attack,
        TargetType::Enemy,
        6,
        0,
    );
    let _rupture = push_draw_top_card(
        &mut state,
        CardId::RuptureCard,
        CardType::Power,
        TargetType::Self_,
        0,
        0,
    );
    // GalvanicPower.BeforeCombatStart Galvanizes the Rupture.
    sts2_core::monster_power_effects::galvanic_before_combat_start(&mut state);
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let cascade_uid = sts2_core::CardUid::new(raw).expect("non-zero");
    state.cards.push(Card {
        uid: cascade_uid,
        card_id: CardId::Cascade,
        cost: -1,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.hand.push(cascade_uid);
    let player_hp = state.player.current_hp;
    let enemy_hp = state.creatures[0].current_hp;
    let _ = play_card(&mut state, 0, None);
    assert_eq!(
        player_hp - state.player.current_hp,
        6,
        "Galvanic dealt its 6"
    );
    assert_eq!(state.player_power_amount(PowerKind::Strength), 1);
    assert_eq!(
        enemy_hp - state.creatures[0].current_hp,
        7,
        "the auto-played Strike already has Rupture's +1 Strength"
    );
    assert!(state.combat_log.rupture_deferred_strength.is_empty());
}

