/// C# `RupturePower` keys its deferred Strength by card
/// (`Dictionary<CardModel,int> playedCards`, RupturePower.cs, both builds):
/// `AfterCardPlayed` applies only the entry of the card that just finished.
/// Offering's self-HP-loss is owed to Offering, so the Strikes Hellraiser
/// auto-plays out of Offering's draw (nested inside its `OnPlay`) must NOT
/// flush it: both hit with the pre-Offering Strength and the +1 lands when
/// Offering finishes. Act23 Ironclad-6029 act 2 @784: C# 9+9, Rust 9+10.
#[test]
fn rupture_offering_strength_not_flushed_by_nested_hellraiser_auto_plays() {
    use sts2_core::combat_loop::play_card;
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    let rupture_pid = NonZeroU32::new(9003).expect("non-zero");
    state.powers.push(Power {
        id: rupture_pid,
        kind: PowerKind::Rupture,
        amount: 1,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(rupture_pid));
    state.init_player_creature();
    let player_uid = state.player.creature_uid.expect("mirror");
    sts2_core::card_effects::apply_power_to_creature(
        &mut state,
        player_uid,
        PowerKind::Hellraiser,
        1,
    );
    state.side = sts2_core::Side::Player;
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.player.energy = 3;
    state.player.max_energy = 3;

    let _filler = push_draw_top_card(
        &mut state,
        CardId::DefendIronclad,
        CardType::Skill,
        TargetType::Self_,
        0,
        5,
    );
    for _ in 0..2 {
        let s = push_draw_top_card(
            &mut state,
            CardId::StrikeIronclad,
            CardType::Attack,
            TargetType::Enemy,
            6,
            0,
        );
        state.cards[s.0.get() as usize - 1].tags = CardTags::one(sts2_core::cards::CardTag::Strike);
    }
    let offering = push_hand_card(&mut state, CardId::Offering);
    {
        let c = &mut state.cards[offering.0.get() as usize - 1];
        c.card_type = CardType::Skill;
        c.target_type = TargetType::Self_;
        c.cost = 0;
        c.base_damage = 0;
    }
    let idx = u8::try_from(
        state
            .player
            .hand
            .iter()
            .position(|&u| u == offering)
            .expect("in hand"),
    )
    .expect("fits");

    let enemy_before = state.creatures[0].current_hp;
    let _ = play_card(&mut state, idx, None);
    assert_eq!(
        enemy_before - state.creatures[0].current_hp,
        12,
        "both nested Strikes hit for 6: Offering's Rupture Strength is still owed",
    );
    assert_eq!(
        state.player_power_amount(PowerKind::Strength),
        1,
        "Offering's deferred Rupture Strength lands once Offering finishes",
    );
}

/// Per-card dispatch smoke: every handler dispatches without panic on
/// a minimal state. (Cards needing `target_uid` get one; others get
/// `None`.) This is the "≥1 unit-test per card" gate.
#[test]
fn every_card_dispatches_without_panic() {
    install_pool();
    for &(id, _) in POOL {
        let (mut state, uid) = fresh_state_with_enemy(200);
        // Push the card onto the Play pile so handlers that touch
        // `current_damage` / `current_block` find an entry.
        let _ = push_play_card(&mut state, id, 6, 5);
        let target = Some(uid);
        let r = dispatch(&mut state, id, target);
        assert_eq!(r, EffectResult::Resolved, "card {id:?} not Resolved");
    }
}

/// Deep pin #1 — Rampage scales via `combat_vars[RampageDamage]`.
///
/// First play: deal 9 base damage, stash +5 for next play.
/// Second play of the SAME card: 9 + 5 = 14 damage. Stash +10.
/// Third play: 9 + 10 = 19 damage. Stash +15.
#[test]
fn rampage_scales_via_combat_vars() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(1000);
    let uid = push_play_card(&mut state, CardId::Rampage, 9, 0);

    // 1st play: 9 damage. Bonus stashed = 5.
    let hp0 = state.creatures[0].current_hp;
    let _ = dispatch(&mut state, CardId::Rampage, Some(enemy));
    let after1 = state.creatures[0].current_hp;
    assert_eq!(hp0 - after1, 9, "1st Rampage = 9 dmg");
    assert_eq!(
        state.cards[uid.0.get() as usize - 1].combat_var(VarKey::RampageDamage),
        5
    );

    // 2nd play: 14 damage. Bonus stashed = 10.
    let _ = dispatch(&mut state, CardId::Rampage, Some(enemy));
    let after2 = state.creatures[0].current_hp;
    assert_eq!(after1 - after2, 14, "2nd Rampage = 14 dmg");
    assert_eq!(
        state.cards[uid.0.get() as usize - 1].combat_var(VarKey::RampageDamage),
        10
    );

    // 3rd play: 19 damage. Bonus stashed = 15.
    let _ = dispatch(&mut state, CardId::Rampage, Some(enemy));
    let after3 = state.creatures[0].current_hp;
    assert_eq!(after2 - after3, 19, "3rd Rampage = 19 dmg");
    assert_eq!(
        state.cards[uid.0.get() as usize - 1].combat_var(VarKey::RampageDamage),
        15
    );
}

/// Deep pin #2 — Whirlwind hits every alive enemy once per energy
/// spent and zeroes out player energy.
#[test]
fn whirlwind_consumes_all_energy_hits_all_enemies() {
    install_pool();
    let (mut state, _) = fresh_state_with_enemy(500);
    // Add a second enemy.
    let id2 = NonZeroU32::new(2).expect("non-zero");
    state.creatures.push(Creature {
        id: id2,
        current_hp: 500,
        max_hp: 500,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(id2));

    // Bead `sts2-rs-eiqfp`: Whirlwind reads `card.energy_spent`
    // (engine stamps this on play). Simulate the engine by stamping
    // 3 onto the just-pushed Whirlwind; energy stays drained.
    let uid = push_play_card(&mut state, CardId::Whirlwind, 5, 0);
    state.cards[uid.0.get() as usize - 1].energy_spent = 3;

    let hp0_a = state.creatures[0].current_hp;
    let hp0_b = state.creatures[1].current_hp;
    let _ = dispatch(&mut state, CardId::Whirlwind, None);

    // 3 X-cost ticks × 5 dmg per tick = 15 damage to each.
    assert_eq!(hp0_a - state.creatures[0].current_hp, 15);
    assert_eq!(hp0_b - state.creatures[1].current_hp, 15);
}

/// Bead `sts2-rs-8z3fl.4`'s sibling `8z3fl.6` — Multi-target
/// Vulnerable scaling on Whirlwind's X-loop. 3 enemies with mixed
/// Vulnerable state (stacks=2 / 0 / 1) take X=3 ticks of 5 base
/// damage each. Per Python pin
/// `sts2-rl-agent@01c094d:sts2_env/powers/common.py::VulnerablePower.modify_damage_multiplicative`
/// + `core/constants.py::VULNERABLE_MULTIPLIER = 1.5`, the
/// multiplier is **presence-gated** (any stack ≥ 1 gives 1.5×)
/// and applied **per damage instance**, NOT per-X-tick-sum. So:
///
/// - Enemy A (Vuln=2) → floor(5 × 1.5) × 3 = 7 × 3 = **21 damage**
/// - Enemy B (Vuln=0) → 5 × 3 = **15 damage** (no multiplier)
/// - Enemy C (Vuln=1) → floor(5 × 1.5) × 3 = 7 × 3 = **21 damage**
///
/// The Vuln=2 vs Vuln=1 distinction is the **stack counter** (turn
/// duration), not a damage-scale knob — this test pins that
/// invariant explicitly so future "Vuln stacks multiplicatively"
/// regressions surface here. Order-of-resolution: Whirlwind's
/// `for _ in 0..x { deal_damage_all_enemies }` consults the per-
/// target Vulnerable on EACH inner call (not once outside the
/// loop) — mirrored by Python's `whirlwind` which iterates
/// `for _ in range(combat.unspent_energy)` calling
/// `calculate_damage` per enemy per tick.
#[test]
fn whirlwind_multi_target_vulnerable_scaling() {
    install_pool();
    let (mut state, enemy_a) = fresh_state_with_enemy(500);

    // Enemy B (Vuln=0 — the control).
    let id_b = NonZeroU32::new(2).expect("non-zero");
    state.creatures.push(Creature {
        id: id_b,
        current_hp: 500,
        max_hp: 500,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let enemy_b = CreatureUid(id_b);
    state.enemy_uids.push(enemy_b);

    // Enemy C (Vuln=1).
    let id_c = NonZeroU32::new(3).expect("non-zero");
    state.creatures.push(Creature {
        id: id_c,
        current_hp: 500,
        max_hp: 500,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let enemy_c = CreatureUid(id_c);
    state.enemy_uids.push(enemy_c);

    // Preload Vulnerable stacks (2 / 0 / 1).
    sts2_core::card_effects::apply_power_to_enemy(&mut state, enemy_a, PowerKind::Vulnerable, 2);
    sts2_core::card_effects::apply_power_to_enemy(&mut state, enemy_c, PowerKind::Vulnerable, 1);

    // Bead `sts2-rs-eiqfp`: stamp `energy_spent` to mirror the
    // engine's pre-dispatch X drain (handler no longer touches
    // `state.player.energy`).
    let uid = push_play_card(&mut state, CardId::Whirlwind, 5, 0);
    state.cards[uid.0.get() as usize - 1].energy_spent = 3;

    let hp0_a = state.creatures[0].current_hp;
    let hp0_b = state.creatures[1].current_hp;
    let hp0_c = state.creatures[2].current_hp;
    let _ = dispatch(&mut state, CardId::Whirlwind, None);

    // Vuln=2 enemy: floor(5 × 1.5) × 3 = 21.
    assert_eq!(
        hp0_a - state.creatures[0].current_hp,
        21,
        "enemy_a (Vuln=2): 3 ticks × floor(5×1.5)=7 = 21"
    );
    // Vuln=0 enemy: 5 × 3 = 15 (no multiplier).
    assert_eq!(
        hp0_b - state.creatures[1].current_hp,
        15,
        "enemy_b (Vuln=0): 3 ticks × 5 = 15 (no multiplier)"
    );
    // Vuln=1 enemy: presence-gated, same multiplier as Vuln=2.
    assert_eq!(
        hp0_c - state.creatures[2].current_hp,
        21,
        "enemy_c (Vuln=1): same as Vuln=2 — multiplier is presence-gated, not stack-scaled"
    );
    assert_eq!(state.player.energy, 0, "Whirlwind zeroes energy");
}

/// Companion to `whirlwind_multi_target_vulnerable_scaling` — same
/// 3-enemy / mixed-Vulnerable shape, but on **Thunderclap**, which
/// is a true single-tick AoE (`AllEnemies` damage + Vulnerable+1).
/// Bead `sts2-rs-8z3fl.6` originally named Fan-of-Knives as the
/// second example, but FanOfKnives at the Python pin is a
/// marker-power + shiv-generation card with no AoE-damage path on
/// its own play (the 2 spawned Shivs each target one enemy in a
/// later play). Thunderclap is the canonical single-card AoE-
/// damage-with-Vulnerable shape and exercises the same per-target
/// multiplier check.
///
/// Test assertions for 4 base damage on enemies (Vuln=2 / 0 / 1):
/// - Enemy A (Vuln=2) takes floor(4 × 1.5) = **6 damage**.
/// - Enemy B (Vuln=0) takes **4 damage**.
/// - Enemy C (Vuln=1) takes **6 damage**.
/// - All three enemies end with +1 stack of Vulnerable applied by
///   Thunderclap's secondary effect (so A=3, B=1, C=2 post-play).
#[test]
fn thunderclap_multi_target_vulnerable_scaling() {
    install_pool();
    let (mut state, enemy_a) = fresh_state_with_enemy(500);

    let id_b = NonZeroU32::new(2).expect("non-zero");
    state.creatures.push(Creature {
        id: id_b,
        current_hp: 500,
        max_hp: 500,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let enemy_b = CreatureUid(id_b);
    state.enemy_uids.push(enemy_b);

    let id_c = NonZeroU32::new(3).expect("non-zero");
    state.creatures.push(Creature {
        id: id_c,
        current_hp: 500,
        max_hp: 500,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let enemy_c = CreatureUid(id_c);
    state.enemy_uids.push(enemy_c);

    sts2_core::card_effects::apply_power_to_enemy(&mut state, enemy_a, PowerKind::Vulnerable, 2);
    sts2_core::card_effects::apply_power_to_enemy(&mut state, enemy_c, PowerKind::Vulnerable, 1);

    let _ = push_play_card(&mut state, CardId::Thunderclap, 4, 0);
    let hp0_a = state.creatures[0].current_hp;
    let hp0_b = state.creatures[1].current_hp;
    let hp0_c = state.creatures[2].current_hp;
    let _ = dispatch(&mut state, CardId::Thunderclap, None);

    assert_eq!(
        hp0_a - state.creatures[0].current_hp,
        6,
        "enemy_a (Vuln=2): floor(4×1.5) = 6"
    );
    assert_eq!(
        hp0_b - state.creatures[1].current_hp,
        4,
        "enemy_b (Vuln=0): 4 (no multiplier)"
    );
    assert_eq!(
        hp0_c - state.creatures[2].current_hp,
        6,
        "enemy_c (Vuln=1): floor(4×1.5) = 6 (presence-gated)"
    );

    // Thunderclap also applies Vulnerable+1 to every enemy AFTER
    // damage. Inspect the post-play stacks (existing helper-style
    // creature.powers walk; mirrors `enemy_power_amount` in
    // sts2-core::relic_effects::tests).
    let stack_of = |uid: CreatureUid| -> i32 {
        let Some(c) = state.creatures.iter().find(|c| c.id == uid.0) else {
            return 0;
        };
        for puid in &c.powers {
            if let Some(p) = state.powers.get_by_id(puid.0) {
                if p.kind == PowerKind::Vulnerable {
                    return p.amount;
                }
            }
        }
        0
    };
    assert_eq!(stack_of(enemy_a), 3, "Vuln 2 → +1 = 3");
    assert_eq!(stack_of(enemy_b), 1, "Vuln 0 → +1 = 1");
    assert_eq!(stack_of(enemy_c), 2, "Vuln 1 → +1 = 2");
}

/// Deep pin #3 — Headbutt deals damage and opens a `PutBack` choice
/// over the discard pile; the chosen card moves to top-of-draw via
/// `apply(Action::ResolveChoice)`. Bead `sts2-rs-419n` lifted this
/// from auto-pick-last-discard to the real choice surface.
#[test]
fn headbutt_moves_discard_card_to_top_of_draw() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    let hb_uid = push_play_card(&mut state, CardId::Headbutt, 9, 0);

    // Pre-seed TWO discarded cards so the decomp opens a choice
    // (FromSimpleGrid pends only for discard.Count >= 2 — see the
    // play_headbutt doc-comment / CardSelectCmd.cs:232).
    let d0 = sts2_core::CardUid::new(99).expect("non-zero");
    let d1 = sts2_core::CardUid::new(98).expect("non-zero");
    state.player.discard.push(d0);
    state.player.discard.push(d1);

    let hp0 = state.creatures[0].current_hp;
    let _ = dispatch(&mut state, CardId::Headbutt, Some(enemy));

    assert_eq!(hp0 - state.creatures[0].current_hp, 9, "Headbutt dmg = 9");
    // Damage applied; choice opened (2 discard cards) but not yet resolved.
    assert!(
        state.pending_choice.is_some(),
        "Headbutt opens a PutBack pending choice for 2+ discard cards"
    );
    // Bead `sts2-rs-8ukqd` (bug D): the played Headbutt is on the Play
    // pile (deferred), so discard still holds exactly the 2 pre-seeded
    // cards — the PutBack option set does NOT include Headbutt.
    assert_eq!(
        state.player.discard.len(),
        2,
        "discard untouched pre-resolve (Headbutt deferred on Play)"
    );

    // Resolve the choice with selection [0] (the first PutBack option).
    let mut sel: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    sel.push(0);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: sel },
    );

    assert!(
        state.pending_choice.is_none(),
        "choice cleared after resolve"
    );
    assert_eq!(
        state.player.draw.first().copied(),
        Some(d0),
        "draw[0] is the moved card"
    );
    // Bead `sts2-rs-8ukqd`: the deferred Headbutt flushes to discard
    // once the choice resolves (C# timing). Discard now holds the
    // un-chosen card (d1) plus the played Headbutt — not the put-back d0.
    assert!(state.player.discard.contains(&hb_uid), "Headbutt flushed");
    assert!(state.player.discard.contains(&d1), "un-chosen card remains");
    assert!(!state.player.discard.contains(&d0), "d0 moved to draw");
    assert!(
        state.player.play.is_empty(),
        "Play pile drained by deferred flush"
    );
}

#[test]
/// Bead `sts2-rs-8ukqd`: with ≤1 discard card, Headbutt AUTO-takes it to
/// the top of draw WITHOUT opening a choice — matching the decomp's
/// `FromSimpleGrid` short-circuit (`cards.Count <= MinSelect`, MinSelect=1).
/// Opening a choice for the single-card case was a Rust bug producing a
/// LEGAL_ACTION_DRIFT vs the auto-resolving game.
fn headbutt_single_discard_auto_takes_no_choice() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    let _hb = push_play_card(&mut state, CardId::Headbutt, 9, 0);
    // Two heterogeneous cards already in draw + BeliefDraw mode, so the
    // RNG-free pinned draw asserted at the end is non-trivial (a >=2-card
    // unknown middle would otherwise consume one RNG read per draw).
    // Bead `sts2-rs-09x5n`.
    let _m0 = push_draw_card(
        &mut state,
        CardId::DefendIronclad,
        CardType::Skill,
        TargetType::Self_,
    );
    let _m1 = push_draw_card(
        &mut state,
        CardId::Anger,
        CardType::Attack,
        TargetType::Enemy,
    );
    state.player.deferred_draw_order = true;
    let d0 = sts2_core::CardUid::new(99).expect("non-zero");
    state.player.discard.push(d0);

    let _ = dispatch(&mut state, CardId::Headbutt, Some(enemy));

    // ≤1 discard → NO choice; the single card auto-moves to draw-top.
    assert!(
        state.pending_choice.is_none(),
        "no choice when discard has one card"
    );
    assert_eq!(
        state.player.draw.first().copied(),
        Some(d0),
        "single discard card auto-moved to draw-top"
    );
    assert!(!state.player.discard.contains(&d0), "card left discard");
    // Bead `sts2-rs-09x5n`: the ≤1-discard fast path bypassed
    // `cards::pin_top` — the ≥2-discard `PutBack` resolver already pinned,
    // so the fast path must too, or MCTS PIMC re-shuffles would scramble a
    // position the player just definitely observed.
    assert_eq!(
        state.player.pinned_top.first().copied(),
        Some(d0),
        "Headbutt's <=1-discard fast path must pin the moved card to Top(0)"
    );
    // The pin is live knowledge, not just list membership: under
    // BeliefDraw, drawing the pinned card consumes NO RNG (no chance
    // node) even with a >=2-card heterogeneous middle beneath it.
    let before = state.run_rng.shuffle.counter();
    let drawn = sts2_core::cards::draw_via_state(&mut state, 1);
    assert_eq!(drawn, 1, "one card drawn");
    assert_eq!(
        state.player.hand.last().copied(),
        Some(d0),
        "the pinned card is the one drawn"
    );
    assert_eq!(
        state.run_rng.shuffle.counter(),
        before,
        "drawing the pinned card must consume NO RNG (deterministic, no chance node)"
    );
}

