// ── Havoc (sts2-rs-tlyk) ─────────────────────────────────────────────
//
// Push a card POD onto `state.cards` and prepend it to the Draw pile
// (top-of-draw). Mirrors `push_play_card` but for the draw pile.
fn push_draw_top_card(
    state: &mut CombatState,
    card_id: CardId,
    card_type: CardType,
    target_type: TargetType,
    base_damage: i32,
    base_block: i32,
) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type,
        target_type,
        upgraded: false,
        base_damage,
        base_block,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.draw.insert(0, uid);
    uid
}

/// Havoc with a normal Attack (Strike-like) on top: the top card is
/// played (damage dealt to the auto-resolved enemy target) and then
/// force-exhausted. Mirrors Python's
/// `auto_play_card(top, force_exhaust=True)` at
/// `sts2-rl-agent@01c094d:sts2_env/core/combat.py:2067-2089` invoked by
/// `ironclad.py::havoc`.
#[test]
fn havoc_plays_and_exhausts_top_attack() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    // Havoc itself on the Play pile (dispatch contract).
    let _ = push_play_card(&mut state, CardId::Havoc, 0, 0);
    // Strike on top of draw — base_damage=6 to match the starter Strike.
    let strike_uid = push_draw_top_card(
        &mut state,
        CardId::StrikeIronclad,
        CardType::Attack,
        TargetType::Enemy,
        6,
        0,
    );

    let hp_before = state.creatures[0].current_hp;
    let r = dispatch(&mut state, CardId::Havoc, None);
    assert_eq!(r, EffectResult::Resolved);

    // Strike's damage landed on the first alive enemy.
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        6,
        "Havoc auto-played Strike for 6 damage",
    );
    // The Strike card is now exhausted, not in draw / hand / discard.
    assert!(
        !state.player.draw.contains(&strike_uid),
        "Strike removed from draw"
    );
    assert!(
        !state.player.discard.contains(&strike_uid),
        "Strike not in discard (force_exhaust)"
    );
    assert!(
        !state.player.hand.contains(&strike_uid),
        "Strike not in hand"
    );
    assert!(
        state.player.exhaust.contains(&strike_uid),
        "Strike in exhaust"
    );
}

/// C# `CardCmd.AutoPlay` runs the card through `OnPlayWrapper`, whose
/// per-iteration `Hook.BeforeCardPlayed` (CardModel.cs:1923) reaches relics
/// too, with `Resources.EnergyValue = EnergyCost.GetAmountToSpend()`
/// (CardCmd.cs:126). So IntimidatingHelmet (`EnergyValue >= 2` → 4 Block)
/// fires for a 2-cost Attack that Havoc auto-plays — the relic channel used to
/// be dispatched for hand plays only.
#[test]
fn havoc_auto_played_two_cost_card_triggers_intimidating_helmet() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    crate::relics::dispatch::ensure_installed();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    state.relics.push(sts2_core::Relic {
        id: std::num::NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::IntimidatingHelmet,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let _ = push_play_card(&mut state, CardId::Havoc, 0, 0);
    let top = push_draw_top_card(
        &mut state,
        CardId::StrikeIronclad,
        CardType::Attack,
        TargetType::Enemy,
        6,
        0,
    );
    state.cards[top.0.get() as usize - 1].cost = 2;
    let block_before = state.player.block;
    let r = dispatch(&mut state, CardId::Havoc, None);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        state.player.block - block_before,
        4,
        "IntimidatingHelmet grants 4 Block on the auto-played 2-cost card",
    );
}

/// Havoc-on-Havoc: the inner Havoc is PLAYED (not guard-exhausted), so its
/// own body auto-plays the card beneath it. Mirrors C# `Havoc.OnPlay` →
/// `AutoPlayFromDrawPile` with no recursion guard
/// (`MegaCrit.Sts2.Core.Models.Cards/Havoc.cs:19-22`). Bead `sts2-rs-cc023`
/// removed the old Rust-side guard that short-circuited the nested Havoc to
/// Exhaust and skipped its body (which skipped the nested reshuffle, the
/// auto-play-family off-by-one).
#[test]
fn havoc_on_havoc_recurses_and_plays_underlying_card() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    // Outer Havoc on Play pile.
    let _ = push_play_card(&mut state, CardId::Havoc, 0, 0);
    // Inner Havoc on top of draw.
    let inner_havoc = push_draw_top_card(
        &mut state,
        CardId::Havoc,
        CardType::Skill,
        TargetType::Self_,
        0,
        0,
    );
    // A Strike *underneath* the inner Havoc — the inner Havoc's body must
    // auto-play it.
    let strike_uid = {
        let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid); // tail = below the inner Havoc
        uid
    };

    let hp_before = state.creatures[0].current_hp;
    let r = dispatch(&mut state, CardId::Havoc, None);
    assert_eq!(r, EffectResult::Resolved);

    // Inner Havoc was played and force-exhausted.
    assert!(
        state.player.exhaust.contains(&inner_havoc),
        "inner Havoc exhausted after being played"
    );
    assert!(
        !state.player.draw.contains(&inner_havoc),
        "inner Havoc no longer in draw"
    );
    // The inner Havoc's body auto-played the Strike underneath it: damage
    // landed AND the Strike force-exhausted.
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        6,
        "inner Havoc recursed and auto-played Strike for 6 damage",
    );
    assert!(
        state.player.exhaust.contains(&strike_uid),
        "Strike force-exhausted by the recursed Havoc",
    );
    assert!(
        !state.player.draw.contains(&strike_uid),
        "Strike consumed from draw",
    );
}

/// Reshuffle window (bead `sts2-rs-cc023`): a Havoc on top of an otherwise
/// EMPTY draw pile must still recurse into its own body, which runs
/// `ShuffleIfNecessary` and refills the draw pile from discard — pulling a
/// stranded discard card back into draw and playing it. The OLD guard
/// exhausted the inner Havoc without running its body, so the discard card
/// stayed put (`discard cs=0 rs=1`). With the guard removed the discard
/// drains to zero, matching the C# trace.
#[test]
fn havoc_on_havoc_reshuffles_discard_into_draw() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    // Outer Havoc on Play pile (the card whose body we dispatch).
    let _ = push_play_card(&mut state, CardId::Havoc, 0, 0);
    // Draw pile holds ONLY an inner Havoc on top — nothing underneath.
    let inner_havoc = push_draw_top_card(
        &mut state,
        CardId::Havoc,
        CardType::Skill,
        TargetType::Self_,
        0,
        0,
    );
    // A Strike sits stranded in DISCARD (e.g. discarded earlier this turn).
    // The inner Havoc's nested ShuffleIfNecessary must reshuffle it into the
    // draw pile and play it.
    let strike_uid = {
        let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.discard.push(uid);
        uid
    };
    assert_eq!(state.player.discard.len(), 1, "Strike starts in discard");

    let hp_before = state.creatures[0].current_hp;
    let r = dispatch(&mut state, CardId::Havoc, None);
    assert_eq!(r, EffectResult::Resolved);

    // The off-by-one is gone: the discard card was reshuffled into draw and
    // played, so the discard ends EMPTY (the `discard cs=0 rs=1` residual).
    assert!(
        state.player.discard.is_empty(),
        "discard drained — reshuffle window matched C# (no stranded card)"
    );
    // Damage landed (the reshuffled Strike was actually played).
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        6,
        "reshuffled Strike auto-played for 6 damage",
    );
    // Both the inner Havoc and the reshuffled Strike force-exhausted.
    assert!(
        state.player.exhaust.contains(&inner_havoc),
        "inner Havoc exhausted"
    );
    assert!(
        state.player.exhaust.contains(&strike_uid),
        "reshuffled Strike force-exhausted"
    );
    assert!(state.player.draw.is_empty(), "draw fully consumed");
}

/// Havoc with an unplayable / no-effect card on top (e.g. Wound, which
/// has no on-play body in this port). The card is force-exhausted; no
/// damage / block etc. Mirrors Python's
/// `auto_play_card(force_exhaust=True)` semantics where an effect-less
/// card still resolves its play and gets exhausted.
#[test]
fn havoc_with_unplayable_top_just_exhausts() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    let _ = push_play_card(&mut state, CardId::Havoc, 0, 0);
    // Wound is a Status (unplayable in Python); in this port its
    // dispatch returns NotImplemented / Resolved with no effect.
    let wound_uid = push_draw_top_card(
        &mut state,
        CardId::Wound,
        CardType::Status,
        TargetType::None,
        0,
        0,
    );

    let hp_before = state.creatures[0].current_hp;
    let pl_hp_before = state.player.current_hp;
    let r = dispatch(&mut state, CardId::Havoc, None);
    assert_eq!(r, EffectResult::Resolved);

    assert_eq!(
        hp_before, state.creatures[0].current_hp,
        "no enemy damage from Wound"
    );
    assert_eq!(pl_hp_before, state.player.current_hp, "no player HP change");
    assert!(
        state.player.exhaust.contains(&wound_uid),
        "Wound force-exhausted"
    );
    assert!(!state.player.draw.contains(&wound_uid), "Wound out of draw");
    assert!(
        !state.player.discard.contains(&wound_uid),
        "Wound NOT routed to discard (force_exhaust)"
    );
}

