/// Push a Skill card into the **hand** pile. Returns its uid.
fn push_hand_skill(state: &mut CombatState, card_id: CardId) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(uid);
    uid
}

/// Parity bug seed 2752 (`PILE_COUNT|POTION:DISTILLED_CHAOS`): a NESTED
/// auto-play must not drop the inner surfacing card. DISTILLED_CHAOS auto-plays
/// HAVOC (`auto_play_n_from_draw_top`); HAVOC auto-plays the next draw-top card
/// BURNING_PACT (`auto_play_card_from_draw_top`); BURNING_PACT surfaces an
/// `ExhaustFromHand` select. Control then unwinds UP into HAVOC's OWN surface
/// gate while BURNING_PACT's select is still pending. Previously HAVOC's gate
/// OVERWROTE the single `pending_autoplay_resume` slot with its own finish,
/// discarding BURNING_PACT's suspended `AutoPlayFinish`; BURNING_PACT's
/// Play→Exhaust disposal never ran and the card was lost from EVERY pile (C#
/// exhaust pile = `[PANIC_BUTTON, LIFT, BURNING_PACT]`, Rust dropped
/// BURNING_PACT). The parent-chain fix parks HAVOC's tail beside BURNING_PACT's
/// instead of clobbering it. Follow-up to bead `sts2-rs-cata-suspend`.
#[test]
fn nested_auto_play_keeps_inner_surfacing_card() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    // TWO hand cards so BURNING_PACT's `ExhaustFromHand` select actually
    // SURFACES — a single option with `min_select >= 1` would auto-resolve
    // inline (C# `HeadlessCardSelector` rule), masking the nesting.
    let hand_card = push_hand_skill(&mut state, CardId::DefendIronclad);
    let _hand_card2 = push_hand_skill(&mut state, CardId::DefendIronclad);
    // Draw pile: HAVOC on top, BURNING_PACT beneath it (push BURNING_PACT first
    // so the later HAVOC push lands above it).
    let burning_pact = push_draw_top_card(
        &mut state,
        CardId::BurningPact,
        CardType::Skill,
        TargetType::Self_,
        0,
        0,
    );
    let havoc = push_draw_top_card(
        &mut state,
        CardId::Havoc,
        CardType::Skill,
        TargetType::Self_,
        0,
        0,
    );

    // DISTILLED_CHAOS-style: auto-play 1 card off the draw top (HAVOC), natural
    // routing (`force_exhaust=false`, the potion's setting).
    sts2_core::combat_loop::auto_play_n_from_draw_top(&mut state, 1, /*force_exhaust=*/ false);

    // BURNING_PACT's exhaust choice SURFACES; HAVOC's tail is parked on the
    // parent chain (NOT clobbering BURNING_PACT's parked finish), and nothing
    // has been exhausted from hand yet.
    assert!(
        state.pending_choice.is_some(),
        "BURNING_PACT's nested exhaust choice surfaces"
    );
    {
        let resume = state
            .pending_autoplay_resume
            .as_ref()
            .expect("the nested auto-play is suspended");
        assert_eq!(
            resume.parent_chain.len(),
            1,
            "HAVOC's tail is parked on the parent chain rather than overwriting BURNING_PACT's finish"
        );
    }
    assert!(
        state.player.play.contains(&burning_pact),
        "BURNING_PACT sits on the Play pile pending its select (not yet disposed)"
    );
    assert!(
        state.player.hand.contains(&hand_card),
        "no hand card is exhausted until the surfaced choice resolves"
    );

    // Resolve the surfaced single-pick exhaust (option 0 = the hand card).
    let pick0: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: pick0 },
    );

    assert!(state.pending_choice.is_none(), "the choice resolved");
    assert!(
        state.pending_autoplay_resume.is_none(),
        "the whole nested auto-play resumed and finished"
    );
    // THE BUG FIX: the inner card is disposed, not lost. HAVOC force-exhausts
    // the card it auto-plays, so BURNING_PACT lands in the EXHAUST pile.
    assert!(
        state.player.exhaust.contains(&burning_pact),
        "BURNING_PACT exhausted (HAVOC force_exhaust=true) — NOT dropped from every pile"
    );
    assert!(
        !state.player.play.contains(&burning_pact),
        "BURNING_PACT left the Play pile"
    );
    // HAVOC itself routes to its natural pile (DistilledChaos force_exhaust=false
    // → discard), and the hand card was exhausted by BURNING_PACT's select.
    assert!(
        state.player.discard.contains(&havoc),
        "HAVOC routed to discard after its parked tail ran"
    );
    assert!(
        state.player.exhaust.contains(&hand_card),
        "the chosen hand card was exhausted by the resumed BURNING_PACT"
    );
}

/// Same nesting as above, but the OUTER `auto_play_n_from_draw_top` batch has a
/// not-yet-played sibling collected AFTER HAVOC. The sibling's replay must be
/// owed to HAVOC's parent-chain frame (so it runs only AFTER HAVOC's tail), not
/// stapled to the inner BURNING_PACT frame. Exercises the
/// `parent_chain.last_mut()` remaining-attach branch.
#[test]
fn nested_auto_play_parent_frame_owes_trailing_sibling() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    // Two hand cards so BURNING_PACT's exhaust select surfaces (see sibling test).
    let hand_card = push_hand_skill(&mut state, CardId::DefendIronclad);
    let _hand_card2 = push_hand_skill(&mut state, CardId::DefendIronclad);
    // Draw (top→bottom): HAVOC, SIBLING (collected with HAVOC), BURNING_PACT
    // (left in draw for HAVOC to auto-play). Push bottom-up.
    let burning_pact = push_draw_top_card(
        &mut state,
        CardId::BurningPact,
        CardType::Skill,
        TargetType::Self_,
        0,
        0,
    );
    let sibling = push_draw_top_card(
        &mut state,
        CardId::DefendIronclad,
        CardType::Skill,
        TargetType::Self_,
        0,
        5,
    );
    let havoc = push_draw_top_card(
        &mut state,
        CardId::Havoc,
        CardType::Skill,
        TargetType::Self_,
        0,
        0,
    );

    // Collect 2 (HAVOC + SIBLING into Play); HAVOC then auto-plays BURNING_PACT
    // off the remaining draw top, which surfaces.
    sts2_core::combat_loop::auto_play_n_from_draw_top(&mut state, 2, /*force_exhaust=*/ false);

    {
        let resume = state
            .pending_autoplay_resume
            .as_ref()
            .expect("the nested auto-play is suspended");
        assert_eq!(
            resume.parent_chain.len(),
            1,
            "HAVOC parked on the parent chain"
        );
        assert_eq!(
            resume.parent_chain[0].remaining.as_slice(),
            &[sibling],
            "the trailing sibling is owed to HAVOC's frame, not the inner BURNING_PACT frame"
        );
        assert!(
            resume.remaining.is_empty(),
            "BURNING_PACT (single auto-play) owes no siblings of its own"
        );
    }

    let pick0: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: pick0 },
    );

    assert!(state.pending_autoplay_resume.is_none(), "fully resumed");
    assert!(
        state.player.exhaust.contains(&burning_pact),
        "inner BURNING_PACT exhausted, not dropped"
    );
    assert!(
        state.player.discard.contains(&havoc),
        "HAVOC routed to discard"
    );
    assert!(
        state.player.discard.contains(&sibling),
        "the trailing sibling replayed (after HAVOC) and routed to discard"
    );
    assert!(
        state.player.exhaust.contains(&hand_card),
        "the hand card was exhausted by BURNING_PACT"
    );
}

/// Thunderclap fan-out: every alive enemy takes damage AND gets
/// Vulnerable.
#[test]
fn thunderclap_hits_all_and_applies_vulnerable() {
    install_pool();
    let (mut state, _) = fresh_state_with_enemy(200);
    let id2 = NonZeroU32::new(2).expect("non-zero");
    state.creatures.push(Creature {
        id: id2,
        current_hp: 200,
        max_hp: 200,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(id2));
    let _ = push_play_card(&mut state, CardId::Thunderclap, 4, 0);

    let hp0_a = state.creatures[0].current_hp;
    let hp0_b = state.creatures[1].current_hp;
    let _ = dispatch(&mut state, CardId::Thunderclap, None);

    // 4 damage to each, plus Vulnerable amplifies if listener runs;
    // here we just assert HP went down at least 4 and Vulnerable was
    // recorded.
    assert!(hp0_a - state.creatures[0].current_hp >= 4);
    assert!(hp0_b - state.creatures[1].current_hp >= 4);
    assert!(state
        .powers
        .iter()
        .any(|p| p.kind == PowerKind::Vulnerable && p.amount >= 1));
}

