/// Bead `sts2-rs-oac` (G3 hand-search plumbing): Armaments auto-picks
/// the FIRST un-upgraded hand card and upgrades it. Verifies (a) block
/// landed, (b) exactly one hand card was upgraded, (c) the FIRST
/// un-upgraded slot was the one chosen (auto-pick determinism).
#[test]
fn armaments_opens_upgrade_choice_and_upgrades_selection() {
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(50);

    // Push 3 hand cards: idx 0 is already upgraded (excluded from the
    // choice), idx 1 + idx 2 are un-upgraded (the two choice options).
    let mut hand_uids: Vec<sts2_core::CardUid> = Vec::new();
    for (i, upgraded) in [true, false, false].iter().enumerate() {
        let raw = u32::try_from(i + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("nz");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: *upgraded,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        hand_uids.push(uid);
    }
    // Push the Armaments card itself (un-upgraded → choice branch).
    let arm_uid = push_play_card(&mut state, CardId::Armaments, 0, 5);

    let r = dispatch(&mut state, CardId::Armaments, None);
    assert_eq!(r, EffectResult::Resolved);

    // Block landed (5 base).
    assert_eq!(state.player.block, 5);

    // Bead `sts2-rs-8ukqd`: base Armaments opens an UpgradeInHand choice
    // over the un-upgraded hand cards (decomp `FromHandForUpgrade`) —
    // nothing is upgraded yet, and the played Armaments is deferred on
    // the Play pile.
    let pc = state.pending_choice.as_ref().expect("choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::UpgradeInHand);
    assert_eq!(pc.options.len(), 2, "two un-upgraded hand options");
    assert_eq!(pc.options[0].card_uid, Some(hand_uids[1]));
    assert_eq!(pc.options[1].card_uid, Some(hand_uids[2]));
    assert!(!state.cards[1].upgraded, "no upgrade pre-resolve");
    assert!(
        state.player.play.contains(&arm_uid),
        "Armaments deferred on Play"
    );

    // Resolve picking option 0 (the first un-upgraded card, idx 1).
    let mut sel: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    sel.push(0);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: sel },
    );

    assert!(state.pending_choice.is_none(), "choice cleared");
    assert!(state.cards[0].upgraded, "idx 0 stays upgraded");
    assert!(state.cards[1].upgraded, "selected card is upgraded");
    assert!(!state.cards[2].upgraded, "unselected card stays as-is");
    // The deferred Armaments flushes to discard on resolve.
    assert!(
        state.player.discard.contains(&arm_uid),
        "Armaments flushes to discard on choice resolve"
    );
    assert!(!state.player.play.contains(&arm_uid), "Play drained");
}

#[test]
/// Bead `sts2-rs-8ukqd`: with exactly ONE upgradable hand card, base
/// Armaments auto-upgrades it WITHOUT opening a choice — matching the
/// decomp `CardSelectCmd.cs:529` (`if (list.Count <= 1) FirstOrDefault`).
/// This is the threshold that avoids the LEGAL_ACTION_DRIFT vs the
/// auto-resolving game.
fn armaments_single_upgradable_auto_upgrades_no_choice() {
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(50);

    // One upgraded (excluded) + one un-upgraded (the sole upgradable).
    for (i, upgraded) in [true, false].iter().enumerate() {
        let raw = u32::try_from(i + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("nz");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: *upgraded,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
    }
    let _arm_uid = push_play_card(&mut state, CardId::Armaments, 0, 5);

    let r = dispatch(&mut state, CardId::Armaments, None);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(state.player.block, 5);
    // ≤1 upgradable → NO choice; the single card is auto-upgraded.
    assert!(
        state.pending_choice.is_none(),
        "no choice when only one upgradable card"
    );
    assert!(state.cards[0].upgraded, "pre-upgraded stays upgraded");
    assert!(state.cards[1].upgraded, "sole upgradable auto-upgraded");
}

