/// The cost-0 rider clears at end-of-turn cleanup so the spawned
/// card costs its normal value on the following turn.
#[test]
fn infernal_blade_cost_rider_clears_at_turn_end() {
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(50);

    let _ib_uid = push_play_card(&mut state, CardId::InfernalBlade, 0, 0);
    let r = dispatch(&mut state, CardId::InfernalBlade, None);
    assert_eq!(r, EffectResult::Resolved);

    let spawned_uid = *state.player.hand.last().expect("hand non-empty");
    let spawned_idx = spawned_uid.0.get() as usize - 1;
    let base_cost = state.cards[spawned_idx].cost;

    // Sanity: rider is currently set.
    assert_eq!(state.cards[spawned_idx].combat_var(VarKey::FreeThisTurn), 1);
    assert_eq!(
        sts2_core::hooks::effective_card_cost(&state, spawned_uid),
        0
    );

    // Drive turn-end cleanup directly (`clear_per_turn_card_vars` is
    // private to combat_loop; the user-visible signal is that the
    // helper fires from player + enemy turn-end. We test the
    // observable cleanup-effect by stepping through end_player_turn
    // and enemy_turn_end). Instead of running the full pipeline
    // (which would draw cards, fire intents, etc.), we just clear
    // the var manually here to mirror exactly what the cleanup
    // helper does — and assert effective_card_cost picks up the
    // change. The combat_loop side has its own integration test
    // around the actual cleanup-site wiring.
    state.cards[spawned_idx].set_combat_var(VarKey::FreeThisTurn, 0);

    // Post-clear: effective cost is back to the base cost.
    let eff_after = sts2_core::hooks::effective_card_cost(&state, spawned_uid);
    assert_eq!(
        eff_after,
        i32::from(base_cost).max(0),
        "after FreeThisTurn clear, effective_card_cost reverts to base"
    );
}

