/// Bead `sts2-rs-16p0`: a second BattleTrance in the same turn is
/// blocked by `NoDraw` (draws 0 cards), the power is applied
/// regardless, and the gate clears at the start of the next player
/// turn so a fresh BT draws 3 again.
#[test]
fn battle_trance_applies_no_draw_and_second_play_is_blocked() {
    use sts2_core::hooks::{dispatch_after_turn_end, TurnSideCtx};
    use sts2_core::CardUid;
    use sts2_core::PowerKind;
    use sts2_core::Side;

    let (mut state, _enemy_uid) = fresh_state_with_enemy(50);

    // Seed five dummy cards into the draw pile so BT₁ can draw 3.
    for i in 1..=5u32 {
        let uid = CardUid::new(i).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: CardId::SetupStrikeCard,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid);
    }

    // Push the (non-upgraded) BT card onto Play so
    // `current_upgraded(state)` reads `false` and BT draws 3.
    let bt_uid = CardUid::new(6).expect("non-zero");
    state.cards.push(Card {
        uid: bt_uid,
        card_id: CardId::BattleTrance,
        cost: 0,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.play.push(bt_uid);

    // First BT: draws 3, applies NoDraw=1.
    let before_hand = state.player.hand.len();
    let _ = play_battle_trance(&mut state, None);
    let after_first = state.player.hand.len();
    assert_eq!(
        after_first - before_hand,
        3,
        "BT₁ should draw 3 (hand grew by 3)",
    );
    let no_draw_amount = state
        .player
        .powers
        .iter()
        .find_map(|uid| {
            state
                .powers
                .iter()
                .find(|p| p.id == uid.0 && p.kind == PowerKind::NoDraw)
                .map(|p| p.amount)
        })
        .unwrap_or(0);
    assert_eq!(no_draw_amount, 1, "NoDraw=1 after BT₁");

    // Second BT in same turn: draws 0, NoDraw stacks to 2.
    let _ = play_battle_trance(&mut state, None);
    let after_second = state.player.hand.len();
    assert_eq!(
        after_second, after_first,
        "BT₂ in same turn should draw 0 (NoDraw blocks)",
    );
    let no_draw_amount_2 = state
        .player
        .powers
        .iter()
        .find_map(|uid| {
            state
                .powers
                .iter()
                .find(|p| p.id == uid.0 && p.kind == PowerKind::NoDraw)
                .map(|p| p.amount)
        })
        .unwrap_or(0);
    assert_eq!(no_draw_amount_2, 2, "NoDraw stacks to 2 after BT₂");

    // Turn boundary: NoDraw is removed at the player's turn END.
    // q6bix F-A relocated the strip from the bead-16p0
    // `start_player_turn` workaround to the C#-faithful
    // `NoDrawPower.AfterTurnEnd` → `PowerCmd.Remove` (unconditional,
    // no side guard). Firing the player-side `after_turn_end` clears it.
    dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
    let no_draw_post = state.player.powers.iter().any(|uid| {
        state
            .powers
            .iter()
            .any(|p| p.id == uid.0 && p.kind == PowerKind::NoDraw)
    });
    assert!(
        !no_draw_post,
        "NoDraw should be removed at the player's turn end",
    );
}

/// Bead `sts2-rs-80kuy`: upgraded BattleTrance draws 4 cards
/// (C# `BattleTrance.cs:OnUpgrade` bumps Cards CardsVar 3→4).
