/// `Stoke` (bead `sts2-rs-tfzwk`): exhaust the entire hand, then add
/// `hand_size` random Ironclad cards to hand from the character pool
/// (C# `CardFactory.GetForCombat(Owner.Character.CardPool, count,
/// Rng.CombatCardGeneration)`). The Draw pile MUST stay untouched —
/// no draw, no shuffle. Prior body (`sts2-rs-vdl`) followed the
/// Python pin and drew that many cards instead.
#[test]
fn stoke_exhausts_hand_and_generates_random_ironclad_cards() {
    install_pool();
    let (mut state, _) = fresh_state_with_enemy(50);
    state.player.character = Some(sts2_core::potions::CharacterId::Ironclad);
    let _ = push_play_card(&mut state, CardId::Stoke, 0, 0);
    let push_pile = |state: &mut CombatState, into_hand: bool| {
        let raw = u32::try_from(state.cards.len() + 1).expect("nz");
        let uid = sts2_core::CardUid::new(raw).expect("nz");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        if into_hand {
            state.player.hand.push(uid);
        } else {
            state.player.draw.push(uid);
        }
    };
    for _ in 0..3 {
        push_pile(&mut state, true);
    }
    for _ in 0..3 {
        push_pile(&mut state, false);
    }
    let draw_before: Vec<_> = state.player.draw.iter().copied().collect();
    let _ = dispatch(&mut state, CardId::Stoke, None);
    assert_eq!(state.player.exhaust.len(), 3, "all 3 hand cards exhausted");
    assert_eq!(
        state.player.hand.len(),
        3,
        "3 fresh Ironclad cards generated into hand"
    );
    let draw_after: Vec<_> = state.player.draw.iter().copied().collect();
    assert_eq!(
        draw_before, draw_after,
        "Draw pile must NOT be touched (C# Stoke generates, never draws)"
    );
    // The new hand cards must be freshly generated (uid > any seeded uid),
    // not the originally-exhausted hand cards.
    let exhausted: std::collections::HashSet<_> = state.player.exhaust.iter().copied().collect();
    for &uid in &state.player.hand {
        assert!(
            !exhausted.contains(&uid),
            "Generated hand cards must be new uids, distinct from the exhausted ones"
        );
    }
}

/// Stoke.cs:33 adds its cards through `CardPileCmd.AddGeneratedCardsToCombat
/// (cards, Hand, Owner)`, which raises `Hook.AfterCardGeneratedForCombat`
/// per card — Pillar of Creation's block fires once per generated card. The
/// hand-rolled body dispatched only the entered-combat bus.
#[test]
fn stoke_fires_card_generated_for_combat_listeners() {
    install_pool();
    let (mut state, _) = fresh_state_with_enemy(50);
    state.player.character = Some(sts2_core::potions::CharacterId::Ironclad);
    let puid = state.init_player_creature();
    sts2_core::card_effects::apply_power_to_creature(
        &mut state,
        puid,
        PowerKind::PillarOfCreation,
        2,
    );
    let _ = push_play_card(&mut state, CardId::Stoke, 0, 0);
    for _ in 0..3 {
        let raw = u32::try_from(state.cards.len() + 1).expect("nz");
        let uid = sts2_core::CardUid::new(raw).expect("nz");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            base_damage: 6,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
    }
    let _ = dispatch(&mut state, CardId::Stoke, None);
    assert_eq!(state.player.hand.len(), 3);
    assert_eq!(
        state.player.block,
        2 * 3,
        "Pillar of Creation per Stoke card"
    );
    assert_eq!(state.count_player_generated_cards_this_combat(), 3);
}

/// `PrimalForce` (bead `sts2-rs-6ynt.7`): every Attack in hand
/// transforms into a `GiantRock`; non-Attack cards are left alone.
/// Mirrors `sts2-rl-agent@01c094d:sts2_env/cards/ironclad.py:1947-1953`.
#[test]
fn primal_force_transforms_only_attacks_in_hand() {
    install_pool();
    let (mut state, _) = fresh_state_with_enemy(50);
    let _ = push_play_card(&mut state, CardId::PrimalForce, 0, 0);
    let seed = |state: &mut CombatState, ct: CardType, id: CardId| {
        let raw = u32::try_from(state.cards.len() + 1).expect("nz");
        let uid = sts2_core::CardUid::new(raw).expect("nz");
        state.cards.push(Card {
            uid,
            card_id: id,
            cost: 1,
            card_type: ct,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: if ct == CardType::Attack { 6 } else { 0 },
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        uid
    };
    let atk_a = seed(&mut state, CardType::Attack, CardId::StrikeIronclad);
    let atk_b = seed(&mut state, CardType::Attack, CardId::Anger);
    let skill = seed(&mut state, CardType::Skill, CardId::DefendIronclad);
    assert_eq!(state.player.hand.len(), 3);

    let _ = dispatch(&mut state, CardId::PrimalForce, None);

    // Hand still has 3 entries — but the two Attack slots now point
    // at fresh GiantRock uids; the Skill slot is untouched.
    assert_eq!(state.player.hand.len(), 3);
    let id_at = |state: &CombatState, uid: sts2_core::CardUid| {
        state.cards[uid.0.get() as usize - 1].card_id
    };
    let hand_ids: Vec<CardId> = state
        .player
        .hand
        .iter()
        .map(|u| id_at(&state, *u))
        .collect();
    let giants = hand_ids
        .iter()
        .filter(|id| **id == CardId::GiantRock)
        .count();
    assert_eq!(giants, 2, "both Attacks became GiantRock");
    assert!(
        hand_ids.contains(&CardId::DefendIronclad),
        "Skill card was not transformed"
    );
    // Old Attack uids are orphaned (no longer in any pile).
    assert!(!state.player.hand.contains(&atk_a));
    assert!(!state.player.hand.contains(&atk_b));
    // Skill uid persists.
    assert!(state.player.hand.contains(&skill));
}

/// `Brand` (empty-hand branch): self-HP-loss + 1 Strength.
