/// Bead `sts2-rs-pe5zo`: Brand with a non-empty hand opens an
/// `ExhaustFromHand` choice (player picks WHICH card to exhaust — not
/// the first), then applies +Strength once the choice resolves. Picks
/// option 1 (the SECOND hand card) to prove it's not hardcoded to
/// `hand.first()`.
#[test]
fn brand_exhausts_selected_card_then_grants_strength() {
    install_pool();
    let (mut state, _) = fresh_state_with_enemy(50);
    // No mirror creature here (like the sibling Brand/Strength tests):
    // the post-effect's legacy fallback applies Strength onto
    // `state.player.powers`, which `player_strength` reads.

    // Two distinct hand cards (idx by uid).
    let mut hand: Vec<sts2_core::CardUid> = Vec::new();
    for i in 1..=2u32 {
        let uid = sts2_core::CardUid::new(i).expect("nz");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            base_damage: 6,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        hand.push(uid);
    }
    let _brand = push_play_card(&mut state, CardId::Brand, 0, 0);
    let hp_pre = state.player.current_hp;

    let _ = dispatch(&mut state, CardId::Brand, None);
    assert!(
        state.player.current_hp < hp_pre,
        "HP loss before the choice"
    );

    let pc = state.pending_choice.as_ref().expect("Brand choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::ExhaustFromHand);
    assert_eq!(pc.options.len(), 2, "both hand cards selectable");
    assert_eq!(
        pc.post_effect,
        Some(sts2_core::PostChoiceEffect::GainStrength(1)),
    );
    // No Strength applied yet (deferred to the resolver).
    assert!(
        !state.player.powers.iter().any(|uid| state
            .powers
            .iter()
            .any(|p| p.id == uid.0 && p.kind == PowerKind::Strength)),
        "Strength deferred until choice resolves",
    );

    // Pick option 1 → exhaust the SECOND hand card (hand[1]).
    let mut sel: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    sel.push(1);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: sel },
    );

    assert!(state.pending_choice.is_none(), "choice cleared");
    assert!(
        state.player.exhaust.contains(&hand[1]),
        "the SELECTED (second) card is exhausted",
    );
    assert!(
        state.player.hand.contains(&hand[0]),
        "the unselected (first) card stays in hand",
    );
    let str_amt = state
        .player
        .powers
        .iter()
        .find_map(|uid| {
            state
                .powers
                .iter()
                .find(|p| p.id == uid.0 && p.kind == PowerKind::Strength)
                .map(|p| p.amount)
        })
        .unwrap_or(0);
    assert_eq!(str_amt, 1, "Strength applied after the exhaust resolves");
}

/// Bead `sts2-rs-pe5zo`: BurningPact with a non-empty hand opens an
/// `ExhaustFromHand` choice and draws `Cards` (2) once it resolves.
/// Picks option 1 to prove the exhaust target is the selected card.
#[test]
fn burning_pact_exhausts_selected_card_then_draws() {
    install_pool();
    let (mut state, _) = fresh_state_with_enemy(50);

    // Two hand cards + four cards in draw to draw from.
    let mut hand: Vec<sts2_core::CardUid> = Vec::new();
    let mut next = 1u32;
    for _ in 0..2 {
        let uid = sts2_core::CardUid::new(next).expect("nz");
        next += 1;
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            base_damage: 6,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        hand.push(uid);
    }
    for _ in 0..4 {
        let uid = sts2_core::CardUid::new(next).expect("nz");
        next += 1;
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            base_damage: 6,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid);
    }
    let _bp = push_play_card(&mut state, CardId::BurningPact, 0, 0);

    let _ = dispatch(&mut state, CardId::BurningPact, None);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("BurningPact choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::ExhaustFromHand);
    assert_eq!(
        pc.post_effect,
        Some(sts2_core::PostChoiceEffect::DrawCards(2)),
    );

    let hand_before = state.player.hand.len();
    let mut sel: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    sel.push(1);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: sel },
    );

    assert!(
        state.player.exhaust.contains(&hand[1]),
        "selected (second) card exhausted",
    );
    assert!(state.player.hand.contains(&hand[0]), "first card retained");
    // Net hand: −1 exhausted + 2 drawn = +1.
    assert_eq!(
        state.player.hand.len(),
        hand_before - 1 + 2,
        "exhaust 1, draw 2",
    );
}

