/// Bead `sts2-rs-k37j`: with `NoDraw` active, every card-effect
/// draw site must yield 0 cards — not just BattleTrance. Covers
/// PommelStrike (Ironclad common attack, draw 1) and BurningPact
/// (Ironclad uncommon, exhaust 1 + draw 2). Mirrors Python's
/// `NoDrawPower.modify_draw_amount → 0` listener which gates the
/// canonical `_draw_cards_for_creature` for the entire turn.
#[test]
fn no_draw_blocks_pommel_strike_and_burning_pact() {
    use sts2_core::PowerKind;

    let (mut state, enemy_uid) = fresh_state_with_enemy(50);

    // Apply NoDraw=1 so the gate is hot.
    apply_power_to_player(&mut state, PowerKind::NoDraw, 1);

    // Stage PommelStrike on the Play pile and seed five draw cards.
    let _ps = push_play_card(&mut state, CardId::PommelStrike, 9, 0);
    for _ in 0..5 {
        let _seed = push_play_card(&mut state, CardId::SetupStrikeCard, 6, 0);
        // Move from play (where push_play_card placed it) to draw.
        let uid = state.player.play.pop().expect("seed uid");
        state.player.draw.push(uid);
    }

    let before = state.player.hand.len();
    let _ = play_pommel_strike(&mut state, Some(enemy_uid));
    assert_eq!(
        state.player.hand.len(),
        before,
        "PommelStrike must draw 0 cards when NoDraw is active",
    );

    // Now stage BurningPact. Pop the PommelStrike off play first so
    // current_damage's `play.last()` resolves to BurningPact.
    let _ = state.player.play.pop();
    let _bp = push_play_card(&mut state, CardId::BurningPact, 0, 0);

    // Seed TWO cards in hand so BurningPact's exhaust is a real choice that
    // surfaces (a single candidate auto-resolves inline, matching C#
    // `FromHand`'s `Count <= MinSelect` auto-select).
    for _ in 0..2 {
        let exh_uid = push_play_card(&mut state, CardId::SetupStrikeCard, 6, 0);
        state.player.play.pop(); // remove from play
        state.player.hand.push(exh_uid);
    }

    let before_bp = state.player.hand.len();
    let _ = play_burning_pact(&mut state, None);
    // Bead `sts2-rs-pe5zo`: BurningPact now opens an ExhaustFromHand
    // choice (player picks the card to exhaust) carrying a
    // `DrawCards` post-effect. Resolve it (pick one of the hand cards).
    let pc = state
        .pending_choice
        .as_ref()
        .expect("BurningPact choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::ExhaustFromHand);
    assert_eq!(
        pc.post_effect,
        Some(sts2_core::PostChoiceEffect::DrawCards(2)),
        "draw-2 post-effect carried on the choice",
    );
    let mut sel: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    sel.push(0);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: sel },
    );
    // The resolver exhausts the selected card (hand −1) and the
    // DrawCards(2) post-effect is gated to 0 by NoDraw.
    assert_eq!(
        state.player.hand.len(),
        before_bp - 1,
        "BurningPact must exhaust 1 and draw 0 when NoDraw is active",
    );
}

// ── sts2-rs-1vv5 — Cascade X-cost auto-play tests ────────────────

/// Cascade unupgraded with `energy_spent = 3` auto-plays exactly
/// 3 cards from the top of the draw pile. Mirrors Python
/// `cascade(card, combat, target)` body at
/// `sts2_env/cards/ironclad.py:1591-1596`. Each auto-played
/// Strike deals 6 damage to the auto-resolved enemy.
#[test]
fn cascade_unupgraded_auto_plays_energy_spent_cards() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);

    // Cascade itself on the Play pile with energy_spent = 3.
    let cascade_uid = push_play_card(&mut state, CardId::Cascade, 0, 0);
    let cascade_idx = cascade_uid.0.get() as usize - 1;
    state.cards[cascade_idx].energy_spent = 3;

    // Seed 4 Strikes on top of draw (4th must NOT play).
    for _ in 0..4 {
        let _ = push_draw_top_card(
            &mut state,
            CardId::StrikeIronclad,
            CardType::Attack,
            TargetType::Enemy,
            6,
            0,
        );
    }

    let hp_before = state.creatures[0].current_hp;
    let r = dispatch(&mut state, CardId::Cascade, None);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        6 * 3,
        "Cascade auto-plays 3 Strikes = 18 damage"
    );
}

