/// Regression for the multi-card auto-play bug (bead `sts2-rs-gpsvo`): when
/// auto-play collects MORE THAN ONE card into the Play pile before resolving
/// them, each card's on-play handler must read ITS OWN stats. The
/// `current_card_{block,damage,upgraded,energy_spent}` helpers read
/// `play.last()`, but `auto_play_n_from_draw_top` pre-collects every card into
/// Play (Phase 1) before resolving (Phase 2) — so for all but the last
/// collected card, `play.last()` was a SIBLING. An auto-played Defend then
/// read the sibling Strike's `base_block` (0) and gained 0 block — the Cascade
/// `player.block` coverage-sweep divergence. The fix rotates each card to
/// `play.last()` before its dispatch.
///
/// The other Cascade tests use only identical Strikes (same stats), so they
/// could never catch this — the interleaved Defend is what exercises it.
#[test]
fn cascade_auto_play_resolves_each_card_with_its_own_stats() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);

    let cascade_uid = push_play_card(&mut state, CardId::Cascade, 0, 0);
    let cascade_idx = cascade_uid.0.get() as usize - 1;
    state.cards[cascade_idx].energy_spent = 2; // auto-play 2 cards

    // Draw top order = [Defend(5 block), Strike(6 dmg)] (each push inserts at
    // the front). Defend is collected/resolved FIRST — i.e. NOT `play.last()`
    // during Phase 2 — which is exactly the case the bug mis-resolved.
    let _strike = push_draw_top_card(
        &mut state,
        CardId::StrikeIronclad,
        CardType::Attack,
        TargetType::Enemy,
        6,
        0,
    );
    let _defend = push_draw_top_card(
        &mut state,
        CardId::DefendIronclad,
        CardType::Skill,
        TargetType::Self_,
        0,
        5,
    );

    let hp_before = state.creatures[0].current_hp;
    let block_before = state.player.block;
    let r = dispatch(&mut state, CardId::Cascade, None);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        state.player.block - block_before,
        5,
        "auto-played Defend must gain its OWN base_block (5), not the sibling Strike's 0",
    );
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        6,
        "auto-played Strike still deals its own 6 damage",
    );
}

/// Bead `sts2-rs-t7qe` — Cascade with `count` larger than the
/// draw pile stops gracefully when `auto_play_card_from_draw_top`
/// returns no card. Mirrors Python `auto_play_from_draw(owner, n)`
/// at `sts2_env/cards/ironclad.py:1591-1596` which iterates `n`
/// times but each iteration is a no-op once the draw pile + the
/// reshuffle-discard pair are exhausted. Regression guard for
/// out-of-bounds / off-by-one bugs in the loop.
#[test]
fn cascade_stops_gracefully_when_draw_pile_runs_out() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);

    // Cascade with energy_spent = 10 → loop wants 10 plays.
    let cascade_uid = push_play_card(&mut state, CardId::Cascade, 0, 0);
    let cascade_idx = cascade_uid.0.get() as usize - 1;
    state.cards[cascade_idx].energy_spent = 10;

    // Only seed 2 Strikes so the loop must short-circuit after
    // play 2 — the remaining 8 iterations should be no-ops.
    for _ in 0..2 {
        let _ = push_draw_top_card(
            &mut state,
            CardId::StrikeIronclad,
            CardType::Attack,
            TargetType::Enemy,
            6,
            0,
        );
    }

    let hp_before = state.creatures[0].current_hp;
    let r = dispatch(&mut state, CardId::Cascade, None);
    assert_eq!(
        r,
        EffectResult::Resolved,
        "Cascade resolves even when draw runs out"
    );
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        6 * 2,
        "Only the 2 available Strikes auto-play; remaining 8 loop iterations are no-ops"
    );
    assert!(
        state.player.draw.is_empty(),
        "Draw pile drained by the available auto-plays"
    );
}

/// Regression for gh#181 (seed 2385, KNIGHTS_ELITE): a HistoryCourse dupe
/// of an auto-play-hook card (Cascade) whose nested auto-play SURFACES a
/// card-select must not drop the surfacing card.
///
/// HistoryCourse re-plays a free dupe of last round's last Attack/Skill via
/// the minimal dupe path (`event_reward.rs::listener_history_course`), which
/// dispatches the dupe's `OnPlay` synchronously and then unconditionally
/// pops it off the Play pile. When the dupe is a Cascade, its OnPlay
/// `AutoPlayFromDrawPile`s the top draw card — here an un-upgraded Armaments,
/// which opens a multi-option `FromHandForUpgrade` select. Without holding
/// `autoplay_inline_resolve`, that select SUSPENDS (parks a
/// `pending_autoplay_resume` with Armaments stranded on Play); the dupe
/// path's pop then corrupts the pile and Armaments vanishes (C# draw
/// `[CASCADE, ARMAMENTS]` vs Rust `[CASCADE]`, player block 10 vs 5).
///
/// The select now prompts the player, as C# does (GH #1131): the dupe goes
/// through the general auto-play path, which parks it under Armaments, and
/// the answer finishes Armaments and then disposes the dupe.
#[test]
fn history_course_dupe_of_cascade_keeps_surfacing_armaments() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    // Register the content relic listeners (HistoryCourse's
    // before_play_phase_start handler lives here, not in the core registry).
    crate::relics::event_reward::install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(200);

    // Round 2+ so HistoryCourse fires (it no-ops on round 1).
    state.round = 2;
    // Equip HistoryCourse.
    state.relics.push(sts2_core::Relic {
        id: std::num::NonZeroU32::new(1).expect("nz"),
        kind: sts2_core::RelicKind::HistoryCourse,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    // Last round's last Attack/Skill was a Cascade — the card HistoryCourse
    // dupes. `src_uid = None` falls back to the spec POD (still X-cost).
    state.combat_log.prev_round_last_attack_skill_played = Some((CardId::Cascade, false, None));
    // X-cost dupe captures current energy as its X; energy = 1 → auto-play 1.
    state.player.energy = 1;

    // Draw top = un-upgraded Armaments (surfaces the upgrade select).
    let arm_uid = push_draw_top_card(
        &mut state,
        CardId::Armaments,
        CardType::Skill,
        TargetType::Self_,
        0,
        5,
    );
    // Two un-upgraded hand cards so Armaments' select has >1 option and
    // SURFACES (a single upgradable card auto-resolves with no choice).
    let s0 = push_hand_card(&mut state, CardId::StrikeIronclad);
    let s1 = push_hand_card(&mut state, CardId::StrikeIronclad);

    let cards_before = state.cards.len();
    let r = sts2_core::relic_effects::dispatch_before_play_phase_start(&mut state);
    assert_eq!(r, EffectResult::Resolved);

    let pc = state.pending_choice.as_ref().expect("Armaments prompts");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::UpgradeInHand);
    assert_eq!(pc.options.len(), 2);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice {
            selection: smallvec::smallvec![0],
        },
    );

    assert!(state.pending_choice.is_none());
    assert!(
        state.pending_autoplay_resume.is_none(),
        "no auto-play resume stranded across the dupe disposal"
    );
    // Armaments was NOT lost: it disposed to discard (then a real combat
    // would reshuffle it back into the draw pile).
    assert!(
        state.player.discard.contains(&arm_uid),
        "Armaments disposed to discard, not dropped"
    );
    assert!(
        !state.player.play.contains(&arm_uid),
        "Armaments left the Play pile"
    );
    assert!(state.player.play.is_empty(), "the dupe is gone too");
    // Its OnPlay ran: 5 block gained + one hand card upgraded (option 0).
    assert_eq!(state.player.block, 5, "Armaments gained its 5 block");
    let upgraded = state.cards[s0.0.get() as usize - 1].upgraded
        || state.cards[s1.0.get() as usize - 1].upgraded;
    assert!(upgraded, "Armaments upgraded one of the hand Strikes");
    // The only new card is the transient Cascade dupe (popped off Play).
    assert_eq!(
        state.cards.len(),
        cards_before + 1,
        "exactly one transient dupe created"
    );
}

/// Bead `sts2-rs-ane8r` — an UNPLAYABLE card (curse / status: Burn,
/// Dazed, Wound, Slimed, AscendersBane, …) sitting on top of the draw
/// pile must NOT be played when an auto-play-from-draw primitive
/// (DistilledChaos / Cascade / Mayhem) reaches it. C#
/// `CardCmd.AutoPlay` short-circuits unplayable cards to
/// `MoveToResultPileWithoutPlaying` (`CardCmd.cs:41-45`,
/// `CardModel.cs:1621-1638`): the card routes to Discard WITHOUT running
/// its on-play body, WITHOUT firing `AfterCardPlayed`, and WITHOUT
/// bumping the cards-played counter. The normal `play_card` path never
/// hits this (unplayable cards are filtered from `legal_actions`), but
/// the auto-play-from-draw path bypasses that filter — this is the
/// DISTILLED_CHAOS sweep-v2 divergence.
///
/// Modelled here with a `keyword_override = UNPLAYABLE` Strike: if the
/// guard were missing the auto-play would dispatch its on-play body and
/// deal 6 damage. With the guard it deals 0 and lands in Discard, while a
/// sibling *playable* Strike still plays normally.
#[test]
fn auto_play_skips_unplayable_card_from_draw_top() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);

    // Bottom of the collected order: a normal playable Strike (6 dmg).
    let _playable = push_draw_top_card(
        &mut state,
        CardId::StrikeIronclad,
        CardType::Attack,
        TargetType::Enemy,
        6,
        0,
    );
    // Top of draw (collected/resolved FIRST): an UNPLAYABLE Strike. Same
    // card body, but the keyword override makes `card_unplayable_inst`
    // true so the guard must skip its on-play dispatch.
    let unplayable = push_draw_top_card(
        &mut state,
        CardId::StrikeIronclad,
        CardType::Attack,
        TargetType::Enemy,
        99, // would be a huge, unmistakable hit if wrongly dispatched
        0,
    );
    let unplayable_idx = unplayable.0.get() as usize - 1;
    state.cards[unplayable_idx].keyword_override =
        Some(sts2_core::cards::KeywordOverride::UNPLAYABLE);

    let hp_before = state.creatures[0].current_hp;
    let attack_plays_before = state.player.cards_played_this_turn[CardType::Attack.index()];

    // Auto-play 2 cards off the top, force_exhaust = false (DistilledChaos
    // / Cascade semantics).
    sts2_core::combat_loop::auto_play_n_from_draw_top(&mut state, 2, false);

    // Only the playable Strike's 6 damage landed — the unplayable Strike's
    // 99-damage body never ran.
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        6,
        "only the playable Strike deals damage; the unplayable card's on-play body must be skipped",
    );
    // The unplayable card routed to Discard (no Exhaust keyword, force_exhaust=false).
    assert!(
        state.player.discard.contains(&unplayable),
        "unplayable auto-played card routes to Discard (MoveToResultPileWithoutPlaying)",
    );
    assert!(
        !state.player.exhaust.contains(&unplayable),
        "unplayable card without Exhaust keyword must NOT exhaust",
    );
    // The unplayable card must NOT have left the Play pile dangling.
    assert!(
        !state.player.play.contains(&unplayable),
        "unplayable card cleaned off the Play pile",
    );
    // Exactly ONE Attack play counted (the playable Strike). The skipped
    // unplayable card must not bump the per-turn play counter.
    assert_eq!(
        state.player.cards_played_this_turn[CardType::Attack.index()] - attack_plays_before,
        1,
        "only the playable card counts as a play; the skipped unplayable one does not",
    );
}

/// C# `CardModel.MoveToResultPileWithoutPlaying` (CardModel.cs:2103-2121,
/// both builds) checks `IsDupe` FIRST and removes a dupe from combat, before
/// the Exhaust / Discard branches. `CardCmd.AutoPlay` takes that route for an
/// Unplayable card and for a `Hook.ShouldPlay` veto (CardCmd.cs:51-73). Act23
/// Ironclad-8184 act 2 @967: Stampede auto-played a Chains-bound dupe Anger,
/// C# removed it, Rust discarded it (discard 16 vs 17). Covers the
/// unplayable and the ShouldPlay-veto guards (here Normality's 4th-play veto).
#[test]
fn auto_play_unplayed_dupe_leaves_combat() {
    for vetoed_by_should_play in [false, true] {
        install_pool();
        sts2_core::card_effects::install_default_registry();
        let (mut state, _enemy) = fresh_state_with_enemy(200);
        let dupe = push_draw_top_card(
            &mut state,
            CardId::Anger,
            CardType::Attack,
            TargetType::Enemy,
            6,
            0,
        );
        let dupe_idx = dupe.0.get() as usize - 1;
        state.cards[dupe_idx].set_combat_var(sts2_core::cards::VarKey::IsDupe, 1);
        if vetoed_by_should_play {
            let normality =
                sts2_core::CardUid::new(u32::try_from(state.cards.len() + 1).expect("fits"))
                    .expect("nz");
            state.cards.push(sts2_core::cards::Card {
                uid: normality,
                card_id: CardId::Normality,
                card_type: CardType::Curse,
                ..sts2_core::cards::Card::pod_defaults()
            });
            state.player.hand.push(normality);
            state.player.card_plays_started_this_turn = 3;
        } else {
            state.cards[dupe_idx].keyword_override =
                Some(sts2_core::cards::KeywordOverride::UNPLAYABLE);
        }
        let hp_before = state.creatures[0].current_hp;
        sts2_core::combat_loop::auto_play_n_from_draw_top(&mut state, 1, false);
        assert_eq!(
            state.creatures[0].current_hp, hp_before,
            "vetoed={vetoed_by_should_play}: the dupe is not played"
        );
        let p = &state.player;
        assert!(
            !p.discard.contains(&dupe)
                && !p.exhaust.contains(&dupe)
                && !p.play.contains(&dupe)
                && !p.hand.contains(&dupe)
                && !p.draw.contains(&dupe),
            "vetoed={vetoed_by_should_play}: an unplayed dupe is removed from combat"
        );
    }
}

