/// Bead `sts2-rs-d9il8`: Dominate applies Vulnerable(1) FIRST, then
/// grants the player Strength equal to the target enemy's *incremented*
/// Vulnerable stack. Faithful to C# `Dominate.OnPlay`.
#[test]
fn dominate_grants_strength_per_target_vulnerable() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(50);
    let _ = push_play_card(&mut state, CardId::Dominate, 0, 0);

    // Stack Vulnerable 3 on the enemy directly.
    apply_power_to_enemy(&mut state, enemy, PowerKind::Vulnerable, 3);
    let baseline_strength = state
        .player
        .powers
        .iter()
        .find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == PowerKind::Strength)
                .map(|p| p.amount)
        })
        .unwrap_or(0);
    assert_eq!(baseline_strength, 0);

    let _ = dispatch(&mut state, CardId::Dominate, Some(enemy));

    let after_strength = state
        .player
        .powers
        .iter()
        .find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == PowerKind::Strength)
                .map(|p| p.amount)
        })
        .unwrap_or(0);
    assert_eq!(
        after_strength, 4,
        "Dominate applies Vulnerable(1) first (3+1=4), then grants Strength = 4"
    );
}

