// ---- xsvp9 follow-up: EvilEye / Spite / TearAsunder conditional --------
// Bead `sts2-rs-xjk9s`. Each handler reads a counter on
// `state.combat_log` (populated by `dispatch_after_card_exhausted` /
// `apply_damage_to_player` at runtime). For these unit tests we set
// the counter directly to exercise both branches without driving the
// full damage / exhaust pipeline.

fn push_self_card(
    state: &mut CombatState,
    card_id: CardId,
    base_damage: i32,
    base_block: i32,
    upgraded: bool,
) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded,
        base_damage,
        base_block,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.play.push(uid);
    uid
}

