/// Local helper: push a card POD into `state.cards` and onto the draw-pile
/// tail (drawn after everything already queued). Attack cards are
/// Strike-tagged so HellraiserPower auto-plays them. Returns the uid.
#[cfg(test)]
fn push_draw_tail(
    state: &mut CombatState,
    card_id: CardId,
    card_type: CardType,
    base_damage: i32,
) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type,
        target_type: if card_type == CardType::Attack {
            TargetType::Enemy
        } else {
            TargetType::Self_
        },
        upgraded: false,
        base_damage,
        base_block: 0,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: if card_type == CardType::Attack {
            CardTags::one(sts2_core::cards::CardTag::Strike)
        } else {
            CardTags::NONE
        },
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.draw.push(uid);
    uid
}

/// Regression (bead `sts2-rs-pillage-hellraiser`): Pillage's do/while
/// attack-draw loop must keep drawing even when HellraiserPower auto-plays
/// (and thus removes from hand) each drawn Strike. C# `Pillage.cs:28-33`
/// keys the loop on the RETURNED drawn card, not the hand size — the Rust
/// port previously inferred "did I draw?" from a hand-length delta, so a
/// Hellraiser auto-play (hand unchanged) broke the loop one card early. The
/// fix routes the drawn card through `state.last_drawn_card`. Sweep seed 459:
/// Pillage won the combat in C# but left both monsters alive in Rust.
#[test]
fn pillage_keeps_drawing_through_hellraiser_autoplay() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(400);
    state.init_player_creature();
    // Apply Hellraiser(1) to the player via its real card path.
    let _ = push_play_card(&mut state, CardId::HellraiserCard, 0, 0);
    let _ = dispatch(&mut state, CardId::HellraiserCard, None);
    assert_eq!(
        state.player_power_amount(PowerKind::Hellraiser),
        1,
        "Hellraiser applied"
    );
    // Three Strikes on top of the draw pile, then a non-Attack terminator.
    push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    let stopper = push_draw_tail(&mut state, CardId::DefendIronclad, CardType::Skill, 0);

    let _ = push_play_card(&mut state, CardId::Pillage, 6, 0);
    let _ = dispatch(&mut state, CardId::Pillage, Some(enemy));

    // Every drawn Strike was auto-played out of hand by Hellraiser; the loop
    // kept going until it drew the non-Attack terminator (kept in hand).
    // Pre-fix the loop broke after the FIRST auto-play, leaving the later
    // Strikes + the terminator undrawn in the draw pile.
    assert!(
        state.player.hand.contains(&stopper),
        "Pillage drew all the way to the non-Attack terminator"
    );
    assert_eq!(
        state.player.hand.len(),
        1,
        "only the terminator sits in hand — all 3 Strikes were auto-played away"
    );
    assert!(
        state.player.draw.is_empty(),
        "the draw pile was fully consumed by Pillage's loop"
    );
}

/// C# `Hook.AfterCardDrawn` (Hook.cs:346-362) runs every `AfterCardDrawnEarly`
/// before any `AfterCardDrawn`: HellraiserPower auto-plays a drawn Strike
/// while it is still unafflicted, and only then does ChainsOfBindingPower
/// afflict it with `Bound`. So the auto-play neither trips Chains'
/// `ShouldPlay` nor sets `boundCardPlayed`, and a second drawn Strike is
/// auto-played too. Rust afflicted first, so the first auto-played Strike set
/// the flag and the second was moved to discard unplayed (act23
/// Ironclad:1007).
#[test]
fn hellraiser_auto_plays_strikes_before_chains_of_binding_binds_them() {
    // Pillage draws until a non-Attack; Hellraiser auto-plays each Strike.
    // Returns (the two Strike uids, the Pillage-played state).
    let run = |chains: i32| {
        install_pool();
        let (mut state, enemy) = fresh_state_with_enemy(400);
        state.init_player_creature();
        let _ = push_play_card(&mut state, CardId::HellraiserCard, 0, 0);
        let _ = dispatch(&mut state, CardId::HellraiserCard, None);
        if chains > 0 {
            // The monster path (Puppet Strings, act3_glory.rs).
            crate::monsters::apply_power_to_player_via_legacy_surface(
                &mut state,
                PowerKind::ChainsOfBinding,
                chains,
            );
        }
        let a = push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
        let b = push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
        let _stopper = push_draw_tail(&mut state, CardId::DefendIronclad, CardType::Skill, 0);
        let _ = push_play_card(&mut state, CardId::Pillage, 6, 0);
        let _ = dispatch(&mut state, CardId::Pillage, Some(enemy));
        ([a, b], state)
    };
    let (_, control) = run(0);
    let ([a, b], state) = run(2);

    assert_eq!(
        state.combat_log.player_card_plays_this_combat,
        control.combat_log.player_card_plays_this_combat,
        "Chains must not block either auto-played Strike",
    );
    assert_eq!(
        state.creatures[0].current_hp,
        control.creatures[0].current_hp
    );
    assert!(
        !state.combat_log.chains_bound_card_played_this_turn,
        "the Strikes were unafflicted when played",
    );
    for uid in [a, b] {
        assert!(
            matches!(
                state.cards[uid.0.get() as usize - 1].affliction,
                Some(sts2_core::card_afflictions::CardAffliction {
                    kind: sts2_core::card_afflictions::CardAfflictionKind::Bound,
                    ..
                })
            ),
            "Chains binds each Strike after its auto-play",
        );
    }
}

/// Hellraiser (via its card) plus `extra` legacy-surface powers, an enemy
/// with `enemy_hp`, and a draw pile of Pommel Strike (a Strike that draws 1)
/// then a Defend. Returns (state, pommel, defend).
#[cfg(test)]
fn hellraiser_pommel_then_defend(
    enemy_hp: i32,
    extra: &[(PowerKind, i32)],
    seed: i32,
) -> (CombatState, sts2_core::CardUid, sts2_core::CardUid) {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(enemy_hp);
    state.run_rng = sts2_core::run_rng_set::RunRngSet::new(seed);
    state.init_player_creature();
    let _ = push_play_card(&mut state, CardId::HellraiserCard, 0, 0);
    let _ = dispatch(&mut state, CardId::HellraiserCard, None);
    for &(kind, amount) in extra {
        crate::monsters::apply_power_to_player_via_legacy_surface(&mut state, kind, amount);
    }
    let pommel = push_draw_tail(&mut state, CardId::PommelStrike, CardType::Attack, 9);
    let defend = push_draw_tail(&mut state, CardId::DefendIronclad, CardType::Skill, 0);
    (state, pommel, defend)
}

/// C# `Hook.AfterCardDrawn` (Hook.cs:345-361, both builds) runs the whole
/// `AfterCardDrawnEarly` pass, then a FRESH `IterateCombatHookListeners` for
/// the normal pass, and that iterator yields nothing once
/// `IsOverOrEnding` (Hook.cs ~100). A Strike HellraiserPower auto-plays in
/// the Early pass that kills the last enemy therefore takes no
/// `ConfusedPower.AfterCardDrawn` cost roll (ConfusedPower.cs:31-45). Rust
/// rolled it before the deferred auto-play, one `CombatEnergyCosts` read
/// ahead into the next fight (act23 Ironclad:6183 act3 @702).
#[test]
fn hellraiser_strike_that_ends_the_combat_takes_no_confused_roll() {
    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(5);
    state.init_player_creature();
    let _ = push_play_card(&mut state, CardId::HellraiserCard, 0, 0);
    let _ = dispatch(&mut state, CardId::HellraiserCard, None);
    crate::monsters::apply_power_to_player_via_legacy_surface(&mut state, PowerKind::Confused, 1);
    let strike = push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    let before = state.run_rng.combat_energy_costs.counter();

    let _ = sts2_core::cards::draw_via_state(&mut state, 1);

    // Auto-played; its move to Discard is refused once the combat is ending
    // (`CardPileCmd.Add`, CardPileCmd.cs:312), so it stays in Play.
    assert!(state.player.play.contains(&strike), "Strike auto-played");
    assert!(sts2_core::combat_loop::combat_is_ending(&state));
    assert_eq!(
        state.run_rng.combat_energy_costs.counter(),
        before,
        "the normal AfterCardDrawn pass is empty once the combat is ending",
    );
}

/// Same Hook.cs:345-361 ordering, non-lethal: the auto-played Pommel
/// Strike's nested draw (the Defend, with its own full `AfterCardDrawn`)
/// resolves inside the Early pass, so the Defend takes the FIRST
/// `CombatEnergyCosts` roll and the Pommel Strike's own Confused roll comes
/// second. Rust rolled the Pommel first.
#[test]
fn hellraiser_nested_draw_rolls_confused_before_the_auto_played_strike() {
    // A seed whose first two `NextInt(4)` rolls differ, so the order shows.
    let seed = (0_i32..10_000)
        .find(|&s| {
            let mut p = sts2_core::run_rng_set::RunRngSet::new(s);
            p.combat_energy_costs.next_int(0, 3) != p.combat_energy_costs.next_int(0, 3)
        })
        .expect("a seed with two distinct first rolls");
    let (mut state, pommel, defend) =
        hellraiser_pommel_then_defend(400, &[(PowerKind::Confused, 1)], seed);
    let mut probe = state.run_rng.combat_energy_costs.clone();
    let first = probe.next_int(0, 3) as i8;
    let second = probe.next_int(0, 3) as i8;

    let _ = sts2_core::cards::draw_via_state(&mut state, 1);

    assert!(state.player.discard.contains(&pommel), "Pommel auto-played");
    assert!(
        state.player.hand.contains(&defend),
        "Pommel drew the Defend"
    );
    assert_eq!(state.cards[defend.0.get() as usize - 1].cost, first);
    assert_eq!(state.cards[pommel.0.get() as usize - 1].cost, second);
}

/// ChainsOfBindingPower.AfterCardDrawn (ChainsOfBindingPower.cs:36-46) is a
/// normal-pass listener that counts this turn's `Bound` `CardAfflictedEntry`s
/// at hook time. With Chains 1, the Defend drawn by the auto-played Pommel
/// Strike (Early pass) takes the only Bound and the Pommel's own Chains call
/// then finds the cap reached. Rust spent the budget on the Pommel before its
/// auto-play (act23 Ironclad:8149 act3 @657, Ironclad:8061 act2 @902).
#[test]
fn hellraiser_nested_draw_takes_chains_budget_before_the_auto_played_strike() {
    let (mut state, pommel, defend) =
        hellraiser_pommel_then_defend(400, &[(PowerKind::ChainsOfBinding, 1)], 0);

    let _ = sts2_core::cards::draw_via_state(&mut state, 1);

    assert!(state.player.discard.contains(&pommel), "Pommel auto-played");
    assert!(
        state.player.hand.contains(&defend),
        "Pommel drew the Defend"
    );
    let bound = |uid: sts2_core::CardUid| {
        matches!(
            state.cards[uid.0.get() as usize - 1].affliction,
            Some(sts2_core::card_afflictions::CardAffliction {
                kind: sts2_core::card_afflictions::CardAfflictionKind::Bound,
                ..
            })
        )
    };
    assert!(bound(defend), "the nested draw is bound first");
    assert!(
        !bound(pommel),
        "the Chains cap was reached before the Pommel"
    );
    assert_eq!(
        state.combat_log.bound_cards_afflicted_by_chains_this_turn,
        1
    );
}

/// HellraiserPower's auto-play (Early pass) reads `EnergyValue =
/// EnergyCost.GetAmountToSpend()` (CardCmd.cs:125-126) BEFORE ConfusedPower's
/// normal-pass `SetThisCombat` roll, so a 2-cost Strike is played at cost 2
/// and IntimidatingHelmet (`EnergyValue >= 2`, IntimidatingHelmet.cs:24-30)
/// grants Block whatever the roll. Rust wrote the roll into the cost first
/// (act23 Ironclad:6183 act3 #b0 @858: player.block cs=8 rs=4).
#[test]
fn hellraiser_auto_play_spends_the_pre_confused_cost() {
    // A seed whose first roll is below 2, so the old order loses the Block.
    let seed = (0_i32..10_000)
        .find(|&s| {
            sts2_core::run_rng_set::RunRngSet::new(s)
                .combat_energy_costs
                .next_int(0, 3)
                < 2
        })
        .expect("a seed with a first roll below 2");
    install_pool();
    sts2_core::card_effects::install_default_registry();
    crate::relics::dispatch::ensure_installed();
    let (mut state, _enemy) = fresh_state_with_enemy(400);
    state.run_rng = sts2_core::run_rng_set::RunRngSet::new(seed);
    state.init_player_creature();
    state.relics.push(sts2_core::Relic {
        id: std::num::NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::IntimidatingHelmet,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let _ = push_play_card(&mut state, CardId::HellraiserCard, 0, 0);
    let _ = dispatch(&mut state, CardId::HellraiserCard, None);
    crate::monsters::apply_power_to_player_via_legacy_surface(&mut state, PowerKind::Confused, 1);
    let strike = push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    state.cards[strike.0.get() as usize - 1].cost = 2;
    let block_before = state.player.block;

    let _ = sts2_core::cards::draw_via_state(&mut state, 1);

    assert!(state.player.discard.contains(&strike), "Strike auto-played");
    assert_eq!(state.player.block - block_before, 4, "played at cost 2");
    assert!(
        state.cards[strike.0.get() as usize - 1].cost < 2,
        "then rolled"
    );
}

/// Regression (bead `sts2-rs-pillage-hellraiser`): Pillage + Hellraiser with
/// no alive enemy must terminate. It used to hang: each drawn Strike was
/// auto-played into an empty board, reshuffled and redrawn forever. With the
/// lone enemy dead the combat is ending, so `CardPileCmd.Draw` moves no card
/// at all (CardPileCmd.cs:822) and the Strikes stay in the draw pile.
#[test]
fn pillage_hellraiser_no_autoplay_without_alive_enemy() {
    install_pool();
    // Enemy already dead → `HittableEnemies` is empty.
    let (mut state, enemy) = fresh_state_with_enemy(10);
    state.creatures[0].current_hp = 0;
    state.init_player_creature();
    let _ = push_play_card(&mut state, CardId::HellraiserCard, 0, 0);
    let _ = dispatch(&mut state, CardId::HellraiserCard, None);

    let s: Vec<_> = (0..4)
        .map(|_| push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6))
        .collect();

    let _ = push_play_card(&mut state, CardId::Pillage, 6, 0);
    // Must TERMINATE (a hang = the bug).
    let _ = dispatch(&mut state, CardId::Pillage, Some(enemy));

    assert_eq!(
        state.player.draw.as_slice(),
        s.as_slice(),
        "an ending combat draws nothing, so nothing is auto-played either"
    );
}

/// Push a Game Piece relic and a played Power card, ready for
/// `dispatch_after_card_played_buses`. Returns the buses' two contexts.
fn game_piece_power_play(
    state: &mut CombatState,
) -> (
    sts2_core::relic_effects::CardEventCtx,
    sts2_core::hooks::CardCtx,
) {
    sts2_core::card_effects::install_default_registry();
    crate::relics::dispatch::ensure_installed();
    state.relics.push(sts2_core::Relic {
        id: std::num::NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::GamePiece,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let power = push_play_card(state, CardId::Inflame, 0, 0);
    state.cards[power.0.get() as usize - 1].card_type = CardType::Power;
    let played_ctx = sts2_core::relic_effects::CardEventCtx {
        card_id: CardId::Inflame,
        card_uid: Some(power),
        target: None,
        card_tags: CardTags::NONE,
        energy_spent: 0,
    };
    let hook_ctx = sts2_core::hooks::CardCtx {
        card_id: Some(CardId::Inflame),
        card_uid: Some(power),
        card_tags: CardTags::NONE,
        card_type: Some(CardType::Power),
    };
    (played_ctx, hook_ctx)
}

/// C# `Hook.AfterCardPlayed` (Hook.cs:422-438) walks
/// `CombatState.IterateHookListeners` (CombatState.cs:117-137): per creature,
/// its Powers, THEN that player's Relics. So the player's `TenderPower`
/// (TenderPower.cs:44-53, Strength -1) lands BEFORE `GamePiece.AfterCardPlayed`
/// (GamePiece.cs:20-25) draws, and the Strike Hellraiser auto-plays off that
/// draw hits at the lowered Strength. Rust ran the relic bus first
/// (Ironclad-6195-a0-act2#b1 @599: HP 68 vs 67).
#[test]
fn tender_drains_strength_before_game_piece_draw_is_auto_played() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    state.init_player_creature();
    let _ = push_play_card(&mut state, CardId::HellraiserCard, 0, 0);
    let _ = dispatch(&mut state, CardId::HellraiserCard, None);
    crate::monsters::apply_power_to_player_via_legacy_surface(&mut state, PowerKind::Tender, 1);
    let _strike = push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    let (played_ctx, hook_ctx) = game_piece_power_play(&mut state);

    sts2_core::combat_loop::dispatch_after_card_played_buses(&mut state, &played_ctx, &hook_ctx);

    let enemy_hp = state
        .creatures
        .iter()
        .find(|c| c.id == enemy.0)
        .expect("enemy")
        .current_hp;
    assert_eq!(
        enemy_hp,
        200 - 5,
        "the auto-played Strike hits at Strength -1 (Tender fired before Game Piece drew)",
    );
}

/// Same listener order as above: the player's `StormPower.AfterCardPlayed`
/// (StormPower.cs:53-63) channels its Lightning BEFORE `GamePiece` draws
/// (Ironclad-6155-a0-act3#b3 @652: Rust drew — and reshuffled — first).
#[test]
fn storm_channels_before_game_piece_draws() {
    use sts2_core::event_log::EventLogEntry;
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    let puid = state.init_player_creature();
    sts2_core::card_effects::apply_power_to_creature(&mut state, puid, PowerKind::Storm, 1);
    sts2_core::hooks::arm_storm_snapshot(&mut state);
    let _drawn = push_draw_tail(&mut state, CardId::DefendIronclad, CardType::Skill, 0);
    let (played_ctx, hook_ctx) = game_piece_power_play(&mut state);
    state.combat_log.event_log.set_recording(true);

    sts2_core::combat_loop::dispatch_after_card_played_buses(&mut state, &played_ctx, &hook_ctx);

    let rows = state.combat_log.event_log.rows();
    let storm = rows
        .iter()
        .position(|r| {
            matches!(
                r.entry,
                EventLogEntry::PowerFlashed {
                    power: PowerKind::Storm,
                    ..
                }
            )
        })
        .expect("Storm fired");
    let drawn = rows
        .iter()
        .position(|r| matches!(r.entry, EventLogEntry::CardDrawn { .. }))
        .expect("Game Piece drew");
    assert!(
        storm < drawn,
        "Storm (player power) fires before Game Piece (relic): {rows:?}"
    );
}

/// Bead `sts2-rs-ench-onplay-order` (mirror corpus records 269/270, 29 live
/// records / 11 `choice_mismatch`): a Swift-enchanted card whose own `OnPlay`
/// opens a hand card-select must offer the **PRE-draw** hand.
///
/// C# `CardModel.OnPlayWrapper` (`CardModel.cs:1930-1943`) awaits the card's
/// own `OnPlay` — including the `CardSelectCmd` inside it — and only THEN runs
/// `Enchantment.OnPlay`. `BurningPact.OnPlay`
/// (`MegaCrit.Sts2.Core.Models.Cards/BurningPact.cs:23-32`) is
/// `CardSelectCmd.FromHand` THEN `CardPileCmd.Draw`, so a Swift(3) BURNING_PACT
/// offers exactly the cards that were in hand when it was played.
///
/// Before the fix the engine fired `Swift.OnPlay` first (the Python
/// `enchantments.on_card_played` site), so the select was built over hand +
/// the 3 cards Swift had already drawn — an injected pick index then resolved
/// to a DIFFERENT card than the player actually chose and every subsequent
/// board diverged. Pins the option count AND the post-choice ordering
/// (BurningPact's own draw, then Swift's).
#[test]
fn ench_onplay_order_swift_burning_pact_selects_pre_draw_hand() {
    use sts2_core::cards::EnchantmentId;
    use sts2_core::CombatPhase;

    install_pool();
    sts2_core::card_effects::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    state.phase = CombatPhase::PlayerPlayPhase;
    state.player.energy = 3;

    // Hand: BURNING_PACT (Swift 3) + two other cards, so the exhaust select
    // actually SURFACES (a single option auto-resolves inline).
    let pact = push_hand_skill(&mut state, CardId::BurningPact);
    state.cards[pact.0.get() as usize - 1].set_enchantment(EnchantmentId::Swift, 3);
    let hand_a = push_hand_skill(&mut state, CardId::DefendIronclad);
    let hand_b = push_hand_skill(&mut state, CardId::DefendIronclad);

    // Draw pile: 8 cards — enough for BurningPact's 2 + Swift's 3.
    let draw: Vec<_> = (0..8)
        .map(|_| push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6))
        .collect();
    let draw_len_before = state.player.draw.len();
    assert_eq!(draw_len_before, 8);

    let r = sts2_core::combat_loop::play_card(&mut state, /*hand_index=*/ 0, None);
    assert_eq!(r, sts2_core::StepResult::PendingChoice);

    // THE FIX: the select sees the hand as it stood at play time — the two
    // sibling hand cards, NOT those plus Swift's 3 draws.
    let choice = state
        .pending_choice
        .as_ref()
        .expect("BURNING_PACT's exhaust select surfaced");
    assert_eq!(
        choice.options.len(),
        2,
        "BurningPact must offer the PRE-Swift-draw hand ({:?}), not hand + Swift's draws",
        choice.options
    );
    let offered: Vec<_> = choice.options.iter().filter_map(|o| o.card_uid).collect();
    assert_eq!(
        offered,
        vec![hand_a, hand_b],
        "exactly the two cards that were in hand when BURNING_PACT was played"
    );
    // Swift has not drawn yet — its `OnPlay` runs after the card body resolves.
    assert_eq!(
        state.player.draw.len(),
        draw_len_before,
        "Swift's draw must not precede the card's own CardSelectCmd"
    );
    for uid in &draw {
        assert!(!state.player.hand.contains(uid), "no Swift draw pre-choice");
    }

    // Resolve the select (option 0 = hand_a).
    let pick0: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: pick0 },
    );
    assert!(state.pending_choice.is_none(), "the select resolved");
    assert!(
        state.player.exhaust.contains(&hand_a),
        "the CHOSEN card was exhausted"
    );

    // Post-resolution: BurningPact's own Draw(2) plus Swift's Draw(3) = 5.
    assert_eq!(
        state.player.draw.len(),
        draw_len_before - 5,
        "BurningPact drew 2 and Swift then drew 3"
    );
    // hand: [hand_b] after the exhaust, + 5 drawn.
    assert_eq!(state.player.hand.len(), 6);
    assert!(state.player.hand.contains(&hand_b));

    // Swift is a first-play-only enchantment: the consumed bit is set.
    assert_ne!(
        state.cards[pact.0.get() as usize - 1]
            .combat_var(sts2_core::cards::VarKey::EnchantmentUsed)
            & 0b0100,
        0,
        "Swift-used bit set after the play finished"
    );
}

/// C# `CardCmd.Exhaust` (`CardCmd.cs:239`) does nothing once the combat is
/// over or ending, so a card Cinder exhausts after its hit kills the last
/// enemy fires no `AfterCardExhausted`: Joss Paper keeps its count (seed
/// GVPEJ1K5D1 at A5: 4 on the game, the engine counted a fifth and wrapped
/// to 0).
#[test]
fn cinder_killing_blow_exhausts_nothing_joss_paper_counts() {
    crate::relics::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state_with_enemy(5);
    state.relics.push(sts2_core::Relic {
        id: NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::JossPaper,
        counter: 4,
        is_wax: false,
        is_melted: false,
    });
    let _ = push_play_card(&mut state, CardId::Cinder, 18, 0);
    let _ = push_hand_card(&mut state, CardId::StrikeIronclad);
    let _ = cinder::play_cinder(&mut state, Some(enemy));
    let counter = state
        .relics
        .iter()
        .find(|r| r.kind == sts2_core::RelicKind::JossPaper)
        .map(|r| r.counter);
    assert_eq!(
        counter,
        Some(4),
        "no exhaust is counted once the fight is ending"
    );
}

/// Exhaust a Defend with Joss Paper (one exhaust from its draw) and Burning
/// Sticks equipped in `relics` order; returns the hand's card ids.
fn joss_paper_and_burning_sticks_hand(relics: [sts2_core::RelicKind; 2]) -> Vec<CardId> {
    install_pool();
    crate::cards::dispatch::ensure_installed();
    crate::relics::dispatch::ensure_installed();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    state.init_player_creature();
    for (i, kind) in relics.into_iter().enumerate() {
        state.relics.push(sts2_core::Relic {
            id: NonZeroU32::new(u32::try_from(i + 1).expect("fits")).expect("non-zero"),
            kind,
            counter: if kind == sts2_core::RelicKind::JossPaper {
                4
            } else {
                0
            },
            is_wax: false,
            is_melted: false,
        });
    }
    push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    let defend = push_hand_card_typed(&mut state, CardId::DefendIronclad, CardType::Skill);
    assert!(sts2_core::card_effects::exhaust_card_uid(
        &mut state, defend
    ));
    state
        .player
        .hand
        .iter()
        .map(|u| state.cards[u.0.get() as usize - 1].card_id)
        .collect()
}

/// C# `Hook.AfterCardExhausted` reaches relics in equip order: Joss Paper
/// equipped first draws before Burning Sticks adds its clone, and vice versa
/// (random-loadout v0.107.1 seed 1176).
#[test]
fn after_card_exhausted_relics_fire_in_equip_order() {
    use sts2_core::RelicKind::{BurningSticks, JossPaper};
    assert_eq!(
        joss_paper_and_burning_sticks_hand([JossPaper, BurningSticks]),
        vec![CardId::StrikeIronclad, CardId::DefendIronclad]
    );
    assert_eq!(
        joss_paper_and_burning_sticks_hand([BurningSticks, JossPaper]),
        vec![CardId::DefendIronclad, CardId::StrikeIronclad]
    );
}

/// The other half of the exhaust rule (C# `CardCmd.Exhaust`, `CardCmd.cs:239`;
/// `Hook.AfterCardExhausted`): an exhaust that began while the combat was live
/// notifies every listener, even if one listener's reaction ends the combat.
/// Dark Embrace (the powers bus, first) draws a Strike that Hellraiser
/// auto-plays into the last enemy; Joss Paper (the relics bus, after) still
/// counts the exhaust. The entry check is asked once, not per bus.
#[test]
fn an_exhaust_whose_reaction_kills_still_reaches_joss_paper() {
    install_pool();
    crate::cards::dispatch::ensure_installed();
    crate::relics::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state_with_enemy(5);
    state.init_player_creature();
    state.relics.push(sts2_core::Relic {
        id: NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::JossPaper,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    for power in [CardId::HellraiserCard, CardId::DarkEmbraceCard] {
        let _ = push_play_card(&mut state, power, 0, 0);
        let _ = dispatch(&mut state, power, None);
    }
    assert_eq!(state.player_power_amount(PowerKind::DarkEmbrace), 1);
    push_draw_tail(&mut state, CardId::StrikeIronclad, CardType::Attack, 6);
    let defend = push_hand_card(&mut state, CardId::DefendIronclad);
    assert!(sts2_core::card_effects::exhaust_card_uid(
        &mut state, defend
    ));
    let enemy_hp = state
        .creatures
        .iter()
        .find(|c| CreatureUid(c.id) == enemy)
        .map(|c| c.current_hp);
    assert_eq!(
        enemy_hp,
        Some(0),
        "the drawn Strike was auto-played into the enemy"
    );
    let counter = state
        .relics
        .iter()
        .find(|r| r.kind == sts2_core::RelicKind::JossPaper)
        .map(|r| r.counter);
    assert_eq!(
        counter,
        Some(1),
        "the exhaust began live: Joss Paper counts it"
    );
}

/// A refused exhaust changes nothing (C# `CardCmd.Exhaust`, `CardCmd.cs:239`;
/// the result-pile switch, `CardModel.cs:1985`). Fiend Fire exhausts the
/// Defend while the combat is live (Joss Paper counts it), then its hit kills
/// the last enemy: its own result-pile exhaust is refused, so Fiend Fire stays
/// in the Play pile and Joss Paper isn't told.
#[test]
fn fiend_fire_after_its_killing_blow_is_not_exhausted() {
    install_pool();
    crate::cards::dispatch::ensure_installed();
    crate::relics::dispatch::ensure_installed();
    let (mut state, _enemy) = fresh_state_with_enemy(5);
    state.init_player_creature();
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.player.energy = 3;
    state.relics.push(sts2_core::Relic {
        id: NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::JossPaper,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let fiend_fire = push_hand_card(&mut state, CardId::FiendFire);
    let defend = push_hand_card_typed(&mut state, CardId::DefendIronclad, CardType::Skill);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::PlayCard {
            hand_index: 0,
            target: Some(0),
        },
    );
    assert!(
        sts2_core::combat_loop::combat_is_ending(&state),
        "the hit killed the enemy"
    );
    assert_eq!(
        state.player.exhaust.as_slice(),
        &[defend],
        "only Defend's exhaust began"
    );
    assert!(
        state.player.play.contains(&fiend_fire),
        "Fiend Fire stays in Play"
    );
    let counter = state
        .relics
        .iter()
        .find(|r| r.kind == sts2_core::RelicKind::JossPaper)
        .map(|r| r.counter);
    assert_eq!(counter, Some(1), "Joss Paper counts Defend only");
}

/// The admission check sits at the exhaust's own boundary, after its
/// prerequisite reshuffle and that reshuffle's reactions (C#
/// `ToastyMittens.cs` awaits `ShuffleIfNecessary` before `CardCmd.Exhaust`,
/// whose check runs then: `CardCmd.cs:239`). The Abacus' block on the reshuffle
/// fires Juggernaut into the last enemy, so the exhaust that follows is
/// refused: both cards stay in the draw pile, Exhaust stays empty and Joss
/// Paper isn't told. Both draw-pile entry points.
#[test]
fn a_reshuffle_that_ends_the_combat_refuses_the_exhaust_after_it() {
    for skip_innate_path in [false, true] {
        install_pool();
        crate::cards::dispatch::ensure_installed();
        crate::relics::dispatch::ensure_installed();
        let (mut state, enemy) = fresh_state_with_enemy(5);
        state.init_player_creature();
        for (raw, kind) in [
            (1, sts2_core::RelicKind::TheAbacus),
            (2, sts2_core::RelicKind::JossPaper),
        ] {
            state.relics.push(sts2_core::Relic {
                id: NonZeroU32::new(raw).expect("non-zero"),
                kind,
                counter: 0,
                is_wax: false,
                is_melted: false,
            });
        }
        let _ = push_play_card(&mut state, CardId::JuggernautCard, 0, 0);
        let _ = dispatch(&mut state, CardId::JuggernautCard, None);
        state.player.play.clear();
        assert!(
            state.player_power_amount(PowerKind::Juggernaut) >= 5,
            "Juggernaut deals at least the enemy's 5 HP"
        );
        let a = push_draw_tail(&mut state, CardId::DefendIronclad, CardType::Skill, 0);
        let b = push_draw_tail(&mut state, CardId::DefendIronclad, CardType::Skill, 0);
        state.player.draw.clear();
        state.player.discard.extend([a, b]);
        if skip_innate_path {
            state.exhaust_top_from_draw_skipping_innate(false);
        } else {
            state.exhaust_from_draw_pile(1);
        }
        let enemy_hp = state
            .creatures
            .iter()
            .find(|c| CreatureUid(c.id) == enemy)
            .map(|c| c.current_hp);
        assert_eq!(
            enemy_hp,
            Some(0),
            "the reshuffle's reactions killed the enemy"
        );
        let mut draw = state.player.draw.to_vec();
        draw.sort_unstable();
        assert_eq!(draw, [a, b], "both cards stay in the draw pile");
        assert!(state.player.exhaust.is_empty(), "the exhaust was refused");
        let counter = state
            .relics
            .iter()
            .find(|r| r.kind == sts2_core::RelicKind::JossPaper)
            .map(|r| r.counter);
        assert_eq!(counter, Some(0), "Joss Paper isn't told");
    }
}

/// Thrash with Pen Nib at `counter` (the value Thrash's own
/// `BeforeCardPlayed` left it at), optionally marked as `AttackToDouble`,
/// exhausting a lone 6-damage attack. Returns (damage the two hits dealt,
/// folded `base_damage`).
fn thrash_under_pen_nib(counter: i32, thrash_is_marked: bool) -> (i32, i32) {
    install_pool();
    crate::relics::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    state.init_player_creature();
    state.relics.push(sts2_core::Relic {
        id: std::num::NonZeroU32::new(1).expect("nz"),
        kind: sts2_core::RelicKind::PenNib,
        counter,
        is_wax: false,
        is_melted: false,
    });
    let thrash = push_play_card(&mut state, CardId::Thrash, /*base_damage=*/ 4, 0);
    if thrash_is_marked {
        state.combat_log.pen_nib_attack_to_double = Some(thrash);
    }
    push_hand_card(&mut state, CardId::StrikeIronclad);
    let hp0 = state.creatures[0].current_hp;
    let _ = dispatch(&mut state, CardId::Thrash, Some(enemy));
    (
        hp0 - state.creatures[0].current_hp,
        state.cards[thrash.0.get() as usize - 1].base_damage,
    )
}

/// Thrash as the 9th attack of a Pen Nib cycle: its hits are in Play, so
/// x1, but the fold's `cardSource` is the exhausted attack, still in Hand.
/// `PenNib.ModifyDamageMultiplicative` (same in v0.107.1 and v0.111.0): with
/// no `AttackToDouble`, a source whose pile is not Play doubles while
/// `AttacksPlayed == 9`, so the fold banks 6 x 2 (`Thrash.cs` OnPlay:
/// `Hook.ModifyDamage(..., cardModel, ...)`; seeds 2008 / 2029 / 2103).
#[test]
fn thrash_fold_on_the_ninth_pen_nib_attack_is_doubled() {
    assert_eq!(thrash_under_pen_nib(9, false), (8, 16));
}

/// Thrash as the marked 10th attack: its own hits double, but the fold's
/// `cardSource` (the exhausted attack) is not `AttackToDouble`, so x1.
#[test]
fn thrash_fold_on_the_marked_tenth_pen_nib_attack_is_not_doubled() {
    assert_eq!(thrash_under_pen_nib(0, true), (16, 10));
}

/// The fold's `Hook.ModifyDamage` applies the exhausted card's enchantment
/// before any listener (v0.111.0 Hook.cs:1643-1652, v0.107.1 Hook.cs:1638):
/// a Corrupted attack (`Corrupted.cs` x1.5 on a powered attack) folds
/// 8 x 1.5 = 12 and a Sharp(+2) one folds 8 + 2 (seed 2158: an exhausted
/// Corrupted Anger+ folded 8 where C# folds 12).
#[test]
fn thrash_fold_applies_the_exhausted_cards_enchantment() {
    use sts2_core::cards::EnchantmentId;
    for version in [
        sts2_core::GameVersion::V0_107_1,
        sts2_core::GameVersion::V0_111_0,
    ] {
        for (ench, amount, want) in [
            (EnchantmentId::Corrupted, 1, 16),
            (EnchantmentId::Sharp, 2, 14),
        ] {
            install_pool();
            let (mut state, enemy) = fresh_state_with_enemy(200);
            state.game_version = version;
            let thrash = push_play_card(&mut state, CardId::Thrash, /*base_damage=*/ 4, 0);
            let picked = push_hand_card(&mut state, CardId::Anger);
            let card = &mut state.cards[picked.0.get() as usize - 1];
            card.base_damage = 8;
            card.set_enchantment(ench, amount);
            let _ = dispatch(&mut state, CardId::Thrash, Some(enemy));
            assert_eq!(
                state.cards[thrash.0.get() as usize - 1].base_damage,
                want,
                "{version}: {ench:?}"
            );
        }
    }
}

/// Corrupted x1.5 composes with Weak x0.75 and Strength in C#'s order:
/// `((8 x 1.5) + 1) x 0.75 = 9.75`, so the fold banks 9 and carries 3/4.
#[test]
fn thrash_fold_enchantment_multiplier_precedes_strength() {
    use sts2_core::cards::EnchantmentId;
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    let thrash = push_play_card(&mut state, CardId::Thrash, /*base_damage=*/ 4, 0);
    let picked = push_hand_card(&mut state, CardId::Anger);
    let card = &mut state.cards[picked.0.get() as usize - 1];
    card.base_damage = 8;
    card.set_enchantment(EnchantmentId::Corrupted, 1);
    for (raw, kind) in [(1, PowerKind::Strength), (2, PowerKind::Weak)] {
        let pid = NonZeroU32::new(raw).expect("non-zero");
        state.powers.push(Power {
            id: pid,
            kind,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(pid));
    }
    let _ = dispatch(&mut state, CardId::Thrash, Some(enemy));
    let t = &state.cards[thrash.0.get() as usize - 1];
    assert_eq!(t.base_damage, 13);
    let (num, den) = (
        t.combat_var(VarKey::ThrashFoldRemNum),
        t.combat_var(VarKey::ThrashFoldRemDen),
    );
    assert_eq!(num * 4, den * 3, "remainder 3/4, got {num}/{den}");
}

/// Exhaust a Drum of Battle carrying `replays` extra plays (Hidden Gem's
/// `BaseReplayCount`) with `power` (stacks) on the player. Returns (energy
/// gained, the power's remaining stacks).
fn drum_exhaust(upgraded: bool, replays: i32, power: Option<(PowerKind, i32)>) -> (i32, i32) {
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    let uid = push_hand_card(&mut state, CardId::DrumOfBattleCard);
    let card = &mut state.cards[uid.0.get() as usize - 1];
    card.upgraded = upgraded;
    card.card_type = CardType::Skill;
    card.target_type = TargetType::Self_;
    card.base_replay_count = replays;
    if let Some((kind, amount)) = power {
        let pid = NonZeroU32::new(1).expect("non-zero");
        state.powers.push(Power {
            id: pid,
            kind,
            amount,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(pid));
    }
    let energy_before = state.player.energy;
    assert!(sts2_core::card_effects::exhaust_card_uid(&mut state, uid));
    let left = power.map_or(0, |(kind, _)| state.player_power_amount(kind));
    (state.player.energy - energy_before, left)
}

/// Drum of Battle gains its energy `GeneratePlayCount` times (v0.111.0
/// DrumOfBattle.cs AfterCardExhausted; CardModel.cs:2029 GeneratePlayCount =
/// `GetEnchantedReplayCount() + 1` through `ModifyCardPlayCount`, same body in
/// v0.107.1). Seed 2112: a Hidden-Gemmed (Replay 2) Drum+ exhausted by Cinder
/// gained 3 x 3 in C#, once in Rust.
#[test]
fn drum_of_battle_exhaust_gains_energy_per_play_count() {
    assert_eq!(drum_exhaust(true, 2, None), (9, 0));
    assert_eq!(drum_exhaust(false, 1, None), (4, 0));
}

/// Burst / Duplication raise the play count of the exhaust reaction too, and
/// `AfterModifyingCardPlayCount` spends a stack (BurstPower.cs,
/// DuplicationPower.cs).
#[test]
fn drum_of_battle_exhaust_play_count_spends_burst_and_duplication() {
    assert_eq!(drum_exhaust(false, 0, Some((PowerKind::Burst, 2))), (4, 1));
    assert_eq!(
        drum_exhaust(false, 0, Some((PowerKind::Duplication, 1))),
        (4, 0)
    );
}

/// C# `CardModel.OnPlayWrapper` moves the played card to its result pile
/// (`CardCmd.Exhaust`, CardModel.cs:1998, firing `AfterCardExhausted`) BEFORE
/// `EnergyCost.AfterCardPlayedCleanup()` (:2007). Burning Sticks clones the
/// exhausted Skill there (`CreateClone` deep-clones `_energyCost` with its
/// local modifiers, CardEnergyCost.cs:411-420), so the clone of a
/// free-this-turn Skill is still free this turn while the original's
/// `WhenPlayed` rider then expires (Ironclad-2184 act 3: an Infernal-Blade-free
/// Skill's clone cost C# 0, Rust 1).
#[test]
fn burning_sticks_clone_of_free_skill_keeps_free_this_turn() {
    use sts2_core::cards::VarKey;
    install_pool();
    crate::cards::dispatch::ensure_installed();
    crate::relics::dispatch::ensure_installed();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    state.init_player_creature();
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.player.energy = 0;
    state.relics.push(sts2_core::Relic {
        id: NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::BurningSticks,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let mut card =
        crate::cards::spec_index::card_pod_from_id(CardId::Impervious, false).expect("spec");
    let imp =
        sts2_core::CardUid::new(u32::try_from(state.cards.len() + 1).expect("fits")).expect("nz");
    card.uid = imp;
    card.set_combat_var(VarKey::FreeThisTurn, 1);
    state.cards.push(card);
    state.player.hand.push(imp);
    let idx = imp.0.get() as usize - 1;
    let r = sts2_core::combat_loop::play_card(&mut state, 0, None);
    assert_eq!(r, sts2_core::StepResult::Advanced);
    assert!(state.player.exhaust.contains(&imp), "Impervious exhausted");
    let clone_uid = *state
        .player
        .hand
        .iter()
        .find(|u| state.cards[u.0.get() as usize - 1].card_id == CardId::Impervious)
        .expect("Burning Sticks cloned the Skill into hand");
    assert_eq!(
        sts2_core::hooks::effective_card_cost(&state, clone_uid),
        0,
        "the clone carries the live free-this-turn modifier"
    );
    assert_eq!(
        state.cards[idx].combat_var(VarKey::FreeThisTurn),
        0,
        "the played original's WhenPlayed rider expired"
    );
}
